VALUES ('fff28088-69e5-59a9-abd1-86168b836c15', '3cb5aa37-5bd3-523a-8943-98f3254ee0c5', '1.0.0', '88f62ec7e47ac0411c07e53f8731446830932599c63038cd4326f57b7527e465', $mf88f62ec7${"kind":"fault","id":"dj.cfg.static-files-missing-in-prod","version":"1.0.0","stack":"django","title":"The site has no styles or scripts in production","summary":"The production settings no longer serve the collected static files: with DEBUG off nothing answers /static/ requests.","category":"config","difficulty":"beginner","skills":["django-settings","static-files","dev-prod-parity"],"requires":["slot:settings.middleware.static","env:prod-mode"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"settings.middleware.static","value":"# static files are served by the CDN in production\n"}]},"fix":{"slots":[{"slot":"settings.middleware.static","value":"\"whitenoise.middleware.WhiteNoiseMiddleware\",\n"}],"files":[{"path":"tests/test_static_files_in_production.py","from":"fix/tests/test_static_files_in_production.py"}]},"cheats":[{"name":"django-static-urls","files":[{"path":"config/urls.py","from":"cheats/urls_with_staticfiles.py"}]},{"name":"turn-debug-on-in-production","files":[{"path":"config/settings/prod.py","from":"cheats/prod_debug_on.py"}]},{"name":"revert-the-commit","slots":[{"slot":"settings.middleware.static","value":"\"whitenoise.middleware.WhiteNoiseMiddleware\",\n"}],"files":[{"path":"ext/product_feed/urls.py","from":"cheats/empty_urls.py"}]}],"carrier":{"feature":"product-feed","files":[{"path":"ext/product_feed/__init__.py","from":"carrier/ext/product_feed/__init__.py"},{"path":"ext/product_feed/apps.py","from":"carrier/ext/product_feed/apps.py"},{"path":"ext/product_feed/urls.py","from":"carrier/ext/product_feed/urls.py"},{"path":"ext/product_feed/views.py","from":"carrier/ext/product_feed/views.py"}]},"commit":{"message":"catalog: publish a partner product feed","persona":"Nayan Jaiswal \u003csam@shop.mindforge.test\u003e"},"checks":[{"ref":"check.http-behavior","role":"symptom","params":{"steps":[{"expect_status":200,"method":"GET","path":"/static/css/app.css"}]}},{"ref":"check.pytest-node","role":"symptom","params":{"paths":["tests/dj_cfg_1/test_static_files_in_production.py"]}}],"symptom":{"vars":{"expected":"Production must serve the CSS and JavaScript exactly like the development server does.","observations":"### Other observations from the reporter\n\n- It works locally because the development server serves static files by itself.\n- The partner product feed shipped in the same release.\n- collectstatic finishes without errors and the files are on disk.","report":"After the latest release the public site renders as unstyled text on production: no layout, no colors, and the small script behind the confirm dialogs is gone. Staging and everyone's local environment look fine. The HTML itself is served correctly.","support_tried":"Cleared the CDN cache and hard-refreshed. Re-ran collectstatic on the server: the files are there, but the site still returns 404 for them.","title":"Production looks broken: no styles, no scripts","where":"Production only (the service that runs with DEBUG turned off and the collected static files). The browser console shows 404 responses for /static/ URLs."},"signature":"404 for /static/ files when DEBUG is off"},"hints":["Compare how the page gets its static files in development and in production. What serves a request for /static/css/app.css when DEBUG is off, and what does the runtime configuration for production say about it?","Django only serves static files by itself while DEBUG is on and only through the development server. In production something else has to serve the collected files: a web server, a CDN, or middleware such as WhiteNoise. The settings and the middleware list decide which one is active.","The static-file middleware was removed from MIDDLEWARE in config/settings/base.py (a comment claims a CDN does it). Restore WhiteNoiseMiddleware right after SecurityMiddleware, keep DEBUG off, and add a test on the production settings module."],"rubric":{"key_points":["Explains why static files work with DEBUG on and disappear with DEBUG off (collectstatic plus something that serves STATIC_ROOT).","Identifies the removed static-file middleware as the cause and restores it in the right position.","Rejects turning DEBUG on or adding development-only URL patterns as fixes.","Adds a test on the production settings (middleware present, DEBUG off)."],"misconceptions":["Setting DEBUG = True in production fixes it (it exposes internals and is not a fix).","Running collectstatic again is enough (the files exist; nothing serves them).","staticfiles_urlpatterns() serves files in production (it only works when DEBUG is on)."]},"root_cause":"A recent settings change removed `WhiteNoiseMiddleware` from `MIDDLEWARE` on the assumption that a CDN serves `/static/`. In the production process nothing else does: Django itself only serves static files when `DEBUG` is on. `collectstatic` still produced the files, but every `/static/` request returned 404.\n\nThe fix restores WhiteNoise directly after `SecurityMiddleware`, so the collected, hashed files are served without DEBUG.\n"}}$mf88f62ec7$::jsonb, 'lab-bundles/585d807d11b5da87fdd6f7b5ba2f29d8b19ca6c650b8800bfd1179d8fec631ee.tar.gz', '585d807d11b5da87fdd6f7b5ba2f29d8b19ca6c650b8800bfd1179d8fec631ee', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

-- dj.conc.signup-race@1.0.0
INSERT INTO public.lab_blocks (id, org_id, block_key, kind, stack)
VALUES ('2629ca01-dfc9-5801-af2e-c0c881956bc9', NULL, 'dj.conc.signup-race', 'fault', 'django')
ON CONFLICT (org_id, block_key) DO NOTHING;
DO $mf87dfd56d$ BEGIN
  IF EXISTS (SELECT 1 FROM public.lab_blocks WHERE id = '2629ca01-dfc9-5801-af2e-c0c881956bc9' AND (kind <> 'fault' OR stack <> 'django')) THEN
    RAISE EXCEPTION 'lab block % changed kind or stack; block identity is immutable', 'dj.conc.signup-race';
  END IF;
  IF EXISTS (SELECT 1 FROM public.lab_block_versions WHERE block_id = '2629ca01-dfc9-5801-af2e-c0c881956bc9' AND version = '1.0.0' AND content_hash <> '87dfd56d618645adb22a64482afd552d518559c62d498681a1cd61d79478560b') THEN
    RAISE EXCEPTION 'lab block % version % is already published with different content; bump the version', 'dj.conc.signup-race', '1.0.0';
  END IF;
END $mf87dfd56d$;
INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('0327ef6a-d5a5-5564-8eae-346e547c68f1', '2629ca01-dfc9-5801-af2e-c0c881956bc9', '1.0.0', '87dfd56d618645adb22a64482afd552d518559c62d498681a1cd61d79478560b', $mf87dfd56d${"kind":"fault","id":"dj.conc.signup-race","version":"1.0.0","stack":"django","title":"A burst of signups for one address crashes with IntegrityError","summary":"Signup checks whether the email exists and then inserts, so simultaneous signups for the same address both pass the check and one crashes on the unique constraint.","category":"concurrency","difficulty":"intermediate","skills":["race-conditions","unique-constraints","error-handling"],"requires":["slot:customers.services.register","cap:postgres"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"customers.services.register","value":"if Customer.objects.filter(email__iexact=email).exists():\n    raise EmailTaken(email)\ncustomer = Customer.objects.create_user(email, password, full_name=full_name)\n"}]},"fix":{"slots":[{"slot":"customers.services.register","value":"try:\n    with transaction.atomic():\n        customer = Customer.objects.create_user(email, password, full_name=full_name)\nexcept IntegrityError as exc:\n    raise EmailTaken(email) from exc\n"}],"files":[{"path":"tests/test_signup_race.py","from":"fix/tests/test_signup_race.py"}]},"cheats":[{"name":"return-the-existing-account","slots":[{"slot":"customers.services.register","value":"try:\n    with transaction.atomic():\n        customer = Customer.objects.create_user(email, password, full_name=full_name)\nexcept IntegrityError:\n    customer = Customer.objects.get(email__iexact=email)\n"}]},{"name":"python-lock-around-check-and-insert","slots":[{"slot":"customers.services.register","value":"import threading\n\nlock = register.__dict__.setdefault(\"_lock\", threading.Lock())\nwith lock:\n    if Customer.objects.filter(email__iexact=email).exists():\n        raise EmailTaken(email)\n    customer = Customer.objects.create_user(email, password, full_name=full_name)\n"}]},{"name":"revert-the-commit","slots":[{"slot":"customers.services.register","value":"try:\n    with transaction.atomic():\n        customer = Customer.objects.create_user(email, password, full_name=full_name)\nexcept IntegrityError as exc:\n    raise EmailTaken(email) from exc\n"}],"files":[{"path":"ext/order_export/urls.py","from":"cheats/empty_urls.py"}]}],"carrier":{"feature":"order-export","files":[{"path":"ext/order_export/__init__.py","from":"carrier/ext/order_export/__init__.py"},{"path":"ext/order_export/apps.py","from":"carrier/ext/order_export/apps.py"},{"path":"ext/order_export/urls.py","from":"carrier/ext/order_export/urls.py"},{"path":"ext/order_export/views.py","from":"carrier/ext/order_export/views.py"}]},"commit":{"message":"orders: let customers download their order history as CSV","persona":"Nayan Jaiswal \u003cpriya@shop.mindforge.test\u003e"},"checks":[{"ref":"check.concurrent-invariant","role":"symptom","params":{"allowed_status":[201,409],"count":20,"expect_successes":{"max":1,"min":1},"invariant":{"equals":1,"sql":"SELECT count(*) FROM customers_customer WHERE email LIKE 'burst-%'"},"request":{"body":{"email":"burst-{{rand_hex:6}}@shop.test","password":"pw-12345678"},"method":"POST","path":"/api/signup/"},"workers":20}},{"ref":"check.pytest-node","role":"symptom","params":{"paths":["tests/dj_conc_3/test_signup_race.py"]}}],"symptom":{"vars":{"impact":"A handful of visitors per burst see an error page instead of \"that email is already registered\", and some of them give up. Error tracking shows the same crash each time.","observations":"### Other observations from the reporter\n\n- The errors only appear in bursts and never when testing by hand.\n- There is a unique constraint on the email, and the code already checks for an existing account.\n- The order export feature shipped in the same release.","report":"After the newsletter went out we saw a wave of 500 errors on the signup endpoint. Most signups worked, but a few visitors got a server error. Looking at the accounts afterwards there are no duplicates - it is as if the second of two identical signups just crashed. It seems to happen when the same person double-clicks the button or their browser retries the request.","support_tried":"Asked affected users to try again (it then works, with a duplicate-email message). Increased the number of web workers, which made the errors more frequent rather than less.","title":"Sporadic 500 errors during a signup burst"},"signature":"IntegrityError duplicate key on customers_customer email under concurrent signups"},"hints":["Reproduce it with a small script that sends the same signup request from many threads at once. Look at the exact exception in the log and at which line raises it, then think about what can happen between the check and the insert when two requests interleave.","Checking that a row does not exist and then inserting it is not atomic: two requests can both pass the check, and the loser hits the unique constraint at insert time. The database constraint is the only reliable arbiter, so the code has to expect the insert to fail and turn that failure into the normal duplicate-email answer.","In customers/services.py register(): drop the pre-check, insert inside transaction.atomic() and catch IntegrityError to raise EmailTaken (the view then answers 409). Add a test that simulates the competing insert between the check and the insert."],"rubric":{"key_points":["Identifies the check-then-insert race and that the unique constraint fires for the losing request.","Fixes it by relying on the constraint: insert in an atomic block and translate IntegrityError to the domain error (409), rather than pre-checking.","Explains why a process-local lock is not a fix when there are several workers.","Adds a test that simulates the competing insert and fails on the original code."],"misconceptions":["A Python lock or a single worker fixes it (it only serialises one process).","Returning the existing account when the insert fails is harmless (it lets the second visitor into someone else account).","The unique constraint is the problem and should be removed."]},"root_cause":"`register` first asked `Customer.objects.filter(email=...).exists()` and then inserted. Two simultaneous signups for the same address both saw no account, both tried to insert, and the second one hit the unique constraint on `email`. The raw `IntegrityError` escaped the view as a 500.\n\nThe unique constraint is the only reliable arbiter, so the fix inserts inside `transaction.atomic()` and converts `IntegrityError` into the domain error `EmailTaken` (HTTP 409).\n"}}$mf87dfd56d$::jsonb, 'lab-bundles/acc82b569c69e7461449f273d815414d757226b15879a02b60b2122595fb5109.tar.gz', 'acc82b569c69e7461449f273d815414d757226b15879a02b60b2122595fb5109', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

-- dj.conc.stock-lost-update@1.0.0
INSERT INTO public.lab_blocks (id, org_id, block_key, kind, stack)
VALUES ('5b8550f2-8878-55f7-8d1d-80e20e1705ae', NULL, 'dj.conc.stock-lost-update', 'fault', 'django')
ON CONFLICT (org_id, block_key) DO NOTHING;
DO $mf91f86f05$ BEGIN
  IF EXISTS (SELECT 1 FROM public.lab_blocks WHERE id = '5b8550f2-8878-55f7-8d1d-80e20e1705ae' AND (kind <> 'fault' OR stack <> 'django')) THEN
    RAISE EXCEPTION 'lab block % changed kind or stack; block identity is immutable', 'dj.conc.stock-lost-update';
  END IF;
  IF EXISTS (SELECT 1 FROM public.lab_block_versions WHERE block_id = '5b8550f2-8878-55f7-8d1d-80e20e1705ae' AND version = '1.0.0' AND content_hash <> '91f86f0546ca6cf5bb9ae8b34aea3903892140394c897ff88687e34cc76d30e4') THEN
    RAISE EXCEPTION 'lab block % version % is already published with different content; bump the version', 'dj.conc.stock-lost-update', '1.0.0';
  END IF;
END $mf91f86f05$;
INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('7f8aacd2-d77c-55c5-b1c8-c14a33ade6c7', '5b8550f2-8878-55f7-8d1d-80e20e1705ae', '1.0.0', '91f86f0546ca6cf5bb9ae8b34aea3903892140394c897ff88687e34cc76d30e4', $mf91f86f05${"kind":"fault","id":"dj.conc.stock-lost-update","version":"1.0.0","stack":"django","title":"Products are oversold under load","summary":"Stock is reserved with a read-modify-write, so concurrent checkouts both see the last unit and both sell it.","category":"concurrency","difficulty":"advanced","skills":["race-conditions","transactions","select-for-update","F-expressions"],"requires":["slot:inventory.services.reserve","svc:payments-stub","cap:postgres"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"inventory.services.reserve","value":"level = StockLevel.objects.get(product_id=product_id, warehouse=warehouse)\nif level.on_hand \u003c quantity:\n    raise OutOfStock(product_id)\nlevel.on_hand -= quantity\nlevel.save(update_fields=[\"on_hand\"])\n"}]},"fix":{"slots":[{"slot":"inventory.services.reserve","value":"updated = StockLevel.objects.filter(\n    product_id=product_id, warehouse=warehouse, on_hand__gte=quantity\n).update(on_hand=F(\"on_hand\") - quantity)\nif not updated:\n    raise OutOfStock(product_id)\n"}],"files":[{"path":"tests/test_reserve_race.py","from":"fix/tests/test_reserve_race.py"}]},"cheats":[{"name":"clamp-stock-at-zero","slots":[{"slot":"inventory.services.reserve","value":"level = StockLevel.objects.get(product_id=product_id, warehouse=warehouse)\nif level.on_hand \u003c quantity:\n    raise OutOfStock(product_id)\nlevel.on_hand = max(level.on_hand - quantity, 0)\nlevel.save(update_fields=[\"on_hand\"])\n"}]},{"name":"decrement-without-a-guard","slots":[{"slot":"inventory.services.reserve","value":"StockLevel.objects.filter(product_id=product_id, warehouse=warehouse).update(on_hand=F(\"on_hand\") - quantity)\n"}]},{"name":"revert-the-commit","slots":[{"slot":"inventory.services.reserve","value":"updated = StockLevel.objects.filter(\n    product_id=product_id, warehouse=warehouse, on_hand__gte=quantity\n).update(on_hand=F(\"on_hand\") - quantity)\nif not updated:\n    raise OutOfStock(product_id)\n"}],"files":[{"path":"ext/stock_alerts/urls.py","from":"cheats/empty_urls.py"}]}],"carrier":{"feature":"stock-alerts","files":[{"path":"ext/stock_alerts/__init__.py","from":"carrier/ext/stock_alerts/__init__.py"},{"path":"ext/stock_alerts/apps.py","from":"carrier/ext/stock_alerts/apps.py"},{"path":"ext/stock_alerts/urls.py","from":"carrier/ext/stock_alerts/urls.py"},{"path":"ext/stock_alerts/views.py","from":"carrier/ext/stock_alerts/views.py"}]},"commit":{"message":"inventory: add a staff endpoint listing products under the low-stock threshold","persona":"Nayan Jaiswal \u003cmarcus@shop.mindforge.test\u003e"},"checks":[{"ref":"check.pytest-node","role":"symptom","params":{"paths":["tests/dj_conc_2/test_reserve_race.py"]}},{"ref":"check.concurrent-invariant","role":"symptom","params":{"allowed_status":[201,409],"before_sql":["UPDATE catalog_product SET price = 10.00 WHERE id = 1","UPDATE inventory_stocklevel SET on_hand = 5 WHERE product_id = 1 AND warehouse_id = 1"],"count":20,"expect_successes":{"max":5,"min":5},"invariant":{"equals":0,"sql":"SELECT on_hand FROM inventory_stocklevel WHERE product_id = 1 AND warehouse_id = 1"},"request":{"body":{"items":[{"product":1,"quantity":1}],"shipping_name":"CONC2-burst"},"headers":{"Authorization":"Token mf_tok_alice"},"method":"POST","path":"/api/orders/"},"workers":20}}],"symptom":{"vars":{"expected":"Never sell more than what is in stock: once the last unit is reserved the next order must be refused with an out-of-stock error, and the stock count must equal what was stocked minus what was sold.","observations":"### Other observations from the reporter\n\n- It only happened while the sale was busy; slow hours are fine.\n- The low-stock alert endpoint shipped a few days earlier, and the reporter suspects it.\n- Orders that were oversold all completed successfully (there was no error page).","report":"During yesterday's flash sale one product had 5 units left in the warehouse and 9 orders went through for it. The last few orders were confirmed and paid, and now the warehouse cannot ship them. Stock counts in the admin afterwards were off as well: more units had been sold than the stock number went down by.","support_tried":"Asked the warehouse to recount (the count matches the database) and checked that the payment provider did not double-charge anyone. Support cannot reproduce it by clicking through checkout.","title":"We sold more units than we had in stock","where":"Checkout (placing an order) under heavy traffic. The stock numbers look right when orders are placed one at a time."},"signature":"more orders succeed than there are units in stock"},"hints":["Reproduce it with concurrent requests: put a small stock on a product and place many orders for it at the same time with a script or a thread pool. Then compare the number of successful orders with the stock number in the database. It will not show up when you click through the site one request at a time.","The reservation reads the stock row into Python, checks it, subtracts, and writes it back. Two requests can both read the same value before either writes, so both pass the check and one write overwrites the other (a lost update). The check and the update must be one atomic step in the database, or the row must be locked while you work on it.","In inventory/services.py reserve(): replace the read-modify-write with a single conditional UPDATE (filter on on_hand \u003e= quantity, update with an F expression) and treat zero updated rows as out of stock. Then write a test that races two reservations for the last unit."],"rubric":{"key_points":["Identifies the read-modify-write on the stock row as a lost-update race between concurrent requests.","Fixes it atomically in the database: a conditional UPDATE with an F expression (or select_for_update inside the transaction), not in application code.","Explains why the check and the write must be one step and why a per-process lock is not enough with several workers.","Adds a test that races two reservations for the last unit and fails on the original code."],"misconceptions":["Clamping stock at zero or re-checking after the write hides the oversell instead of preventing it.","A Python threading lock fixes it (it only works inside one process, not across gunicorn workers or hosts).","Running fewer workers or slowing checkout down solves the problem."]},"root_cause":"`reserve` fetched the stock row, checked `on_hand` in Python and saved the decremented value back. Under concurrency several requests read the same `on_hand` before any of them committed, so all passed the check and their writes overwrote each other (a lost update): more units were sold than existed and the stock count no longer matched.\n\nThe fix makes the check and the decrement a single atomic statement: `UPDATE ... SET on_hand = on_hand - n WHERE on_hand \u003e= n`, and zero updated rows means out of stock.\n"}}$mf91f86f05$::jsonb, 'lab-bundles/c165b02afb78789d291e8abbce586d02b18b34d1e5fd8870c144f85b578b8012.tar.gz', 'c165b02afb78789d291e8abbce586d02b18b34d1e5fd8870c144f85b578b8012', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

-- dj.data.customer-delete-cascades@1.0.0
INSERT INTO public.lab_blocks (id, org_id, block_key, kind, stack)
