DO $mf6be615be$ BEGIN
  IF EXISTS (SELECT 1 FROM public.lab_blocks WHERE id = 'b4a8aecb-c98e-54af-af83-7616fa637262' AND (kind <> 'fault' OR stack <> 'django')) THEN
    RAISE EXCEPTION 'lab block % changed kind or stack; block identity is immutable', 'dj.data.customer-delete-cascades';
  END IF;
  IF EXISTS (SELECT 1 FROM public.lab_block_versions WHERE block_id = 'b4a8aecb-c98e-54af-af83-7616fa637262' AND version = '1.0.0' AND content_hash <> '6be615beea1843109a452ab18bdc6100cf13eb938ac42b14ad7cfcd8b593d483') THEN
    RAISE EXCEPTION 'lab block % version % is already published with different content; bump the version', 'dj.data.customer-delete-cascades', '1.0.0';
