  END IF;
  IF EXISTS (SELECT 1 FROM public.lab_block_versions WHERE block_id = 'a13288fb-e55d-5d7a-b555-c58fc69d98cf' AND version = '1.0.0' AND content_hash <> 'b4baa0dddec3ae97583b4527cb27ee5825cffa06049dec823ee2afbbf8d82ce3') THEN
