    RAISE EXCEPTION 'lab block % changed kind or stack; block identity is immutable', 'dj.perf.dashboard-repeated-queries';
  END IF;
  IF EXISTS (SELECT 1 FROM public.lab_block_versions WHERE block_id = 'd36e2afc-0ffc-501c-91fa-d51de683be60' AND version = '1.0.0' AND content_hash <> '49fcd788fdcb564b1e7cf3c5e1b3264ad1ad94dca6fbf9923e50e6f2f1de5dde') THEN
    RAISE EXCEPTION 'lab block % version % is already published with different content; bump the version', 'dj.perf.dashboard-repeated-queries', '1.0.0';
