ON CONFLICT (org_id, block_key) DO NOTHING;
DO $mf7718466e$ BEGIN
  IF EXISTS (SELECT 1 FROM public.lab_blocks WHERE id = 'd8079750-d118-50c6-a0f2-4225a750f37e' AND (kind <> 'fault' OR stack <> 'fastapi')) THEN
