INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('2cd187d1-a611-5668-bf74-451272de0ba8', '3149cf97-f959-5bb6-9f10-4049a669a0dc', '1.0.0', 'a2a0eb2e0f4879912956044827c8e15349e5236c86150edb0b017793765a414c', $mfa2a0eb2e${"kind":"fault","id":"fa.async.wallet-lost-update","version":"1.0.0","stack":"fastapi","title":"Wallet balances are wrong when several top-ups arrive at once","summary":"The balance is read, increased in Python and written back across an await, so concurrent credits overwrite each other and money disappears.","category":"async","difficulty":"advanced","skills":["asyncio","transactions","row-locking","concurrency"],"requires":["slot:wallet.service.apply_credit","cap:postgres"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"wallet.service.apply_credit","value":"current = (await session.execute(select(Customer.credit_cents).where(Customer.id == customer_id))).scalar_one()\nbalance = current + amount_cents\nawait session.execute(update(Customer).where(Customer.id == customer_id).values(credit_cents=balance))\n"}]},"fix":{"slots":[{"slot":"wallet.service.apply_credit","value":"result = await session.execute(\n    update(Customer)\n    .where(Customer.id == customer_id)\n    .values(credit_cents=Customer.credit_cents + amount_cents)\n    .returning(Customer.credit_cents)\n)\nbalance = result.scalar_one()\n"}],"files":[{"path":"tests/test_wallet_concurrency.py","from":"fix/tests/test_wallet_concurrency.py"}]},"cheats":[{"name":"process-local-lock","slots":[{"slot":"wallet.service.apply_credit","value":"import asyncio\n\nlock = apply_credit.__dict__.setdefault(\"lock\", asyncio.Lock())\nasync with lock:\n    current = (await session.execute(select(Customer.credit_cents).where(Customer.id == customer_id))).scalar_one()\n    balance = current + amount_cents\n    await session.execute(update(Customer).where(Customer.id == customer_id).values(credit_cents=balance))\n"}]},{"name":"revert-the-commit","slots":[{"slot":"wallet.service.apply_credit","value":"result = await session.execute(\n    update(Customer)\n    .where(Customer.id == customer_id)\n    .values(credit_cents=Customer.credit_cents + amount_cents)\n    .returning(Customer.credit_cents)\n)\nbalance = result.scalar_one()\n"}],"files":[{"path":"app/ext/account_overview.py","from":"cheats/empty_ext.py"}]}],"carrier":{"feature":"account-overview","files":[{"path":"app/ext/account_overview.py","from":"carrier/app/ext/account_overview.py"}]},"commit":{"message":"wallet: show the store credit balance on the account overview","persona":"Nayan Jaiswal \u003cmarcus@shop.mindforge.test\u003e"},"checks":[{"ref":"check.concurrent-invariant","role":"symptom","params":{"allowed_status":[200],"before_sql":["UPDATE customers SET credit_cents = 0 WHERE email = 'alice@shop.test'"],"count":20,"invariant":{"equals":2000,"sql":"SELECT credit_cents FROM customers WHERE email = 'alice@shop.test'"},"request":{"body":{"amount_cents":100,"reason":"probe"},"headers":{"Authorization":"Bearer mf_tok_alice"},"method":"POST","path":"/api/v1/wallet/credit"},"workers":10}},{"ref":"check.pytest-node","role":"symptom","params":{"paths":["tests/fa_async_7/test_wallet_concurrency.py"]}}],"symptom":{"vars":{"expected":"The balance must always equal the sum of the credits in the ledger, however many arrive at once.","observations":"### Other observations from the reporter\n\n- Single credits always work. The problem needs concurrency.\n- The ledger rows are correct and record a `balance_after_cents` that is wrong for the later row.\n- The account overview endpoint (shipped last week) reads the same balance and shows the wrong number, so it is not a display problem.","report":"During Saturday's \"double credit\" promotion the app showed some customers a lower store credit than they were promised. Several customers\ntopped up or received promotional credit within the same second (from the app and from the promo job), and afterwards their balance was\nshort by one or more of the credits. The ledger lists every credit, but the balance does not add up to it.","support_tried":"Compared balances with the ledger for 40 affected customers: every difference is an exact multiple of a credit that was applied \"at the same time\"\nas another. Support credited the missing amounts manually.","title":"Customers say their store credit is missing after a promotion","where":"`POST /api/v1/wallet/credit` and the balance shown by `GET /api/v1/wallet`. It only happens when two or more credits for the same customer are\nin flight at the same time, so it is hard to reproduce by hand."},"signature":"wallet balance lower than the sum of its ledger credits"},"hints":["Reproduce it with concurrency, not by hand. Fire several credits for the same customer at once (a thread pool of requests with httpx, or `asyncio.gather` in a script) and compare the balance with the sum of the ledger. Fewer or more workers change how often it happens.","Read `apply_credit` as two steps with an `await` between them: read the current balance, then write `current + amount`. Two requests can both read the same balance before either writes. Each `await` is a point where another request runs, so \"read then write\" is not atomic.","Let the database do the arithmetic in one statement (`UPDATE ... SET credit_cents = credit_cents + :amount RETURNING credit_cents`), or lock the row first with `SELECT ... FOR UPDATE`. An in-process lock is not enough once there is more than one worker. Add a test that runs many credits concurrently."],"rubric":{"key_points":["Identifies a lost update - a read-modify-write that spans awaits (and transactions), so concurrent requests overwrite each other.","Explains why asyncio does not make this safe - every await is a scheduling point, and the race is in the database round trips.","Fixes it in the database (atomic UPDATE ... RETURNING, or SELECT FOR UPDATE) rather than with a process-local lock.","Adds a concurrent test that fails on the original code and checks the balance against the ledger."],"misconceptions":["Because asyncio is single-threaded there are no race conditions (the race is across awaits and database round trips).","An asyncio.Lock fixes it (it does not protect a second worker or a second instance).","Retrying or sleeping before the write fixes it."]},"root_cause":"`apply_credit` read the customer's balance, added the credit in Python and wrote the result back. Between the read and the write the coroutine awaits the database, and other requests run. Two credits that read the same balance both write `balance + amount`, so one of them is lost, while the ledger still records both.\n\nThe fix moves the arithmetic into a single `UPDATE ... SET credit_cents = credit_cents + :amount RETURNING credit_cents`. PostgreSQL takes the row lock for the update, so concurrent credits apply one after another and each sees the previous result. `SELECT ... FOR UPDATE` before the write is the other correct option; a process-local lock is not, because it does not protect several workers."}}$mfa2a0eb2e$::jsonb, 'lab-bundles/4083fa56b54b4bbe49637c0be64950d7b585d20c4c4889b313904661fe943983.tar.gz', '4083fa56b54b4bbe49637c0be64950d7b585d20c4c4889b313904661fe943983', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

-- fa.cfg.docs-ignore-root-path@1.0.0
