INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('a2b729ce-362a-5286-956d-13df67739048', '62c4ed23-c268-5b98-8106-7f19c7d5c97e', '1.0.0', '281e3a0b705c1ab93d941ab2dc0d6413b8084109f6326147a647652b3cf5203a', $mf281e3a0b${"kind":"fault","id":"fa.err.payment-failure-returns-200","version":"1.0.0","stack":"fastapi","title":"Monitoring shows no payment errors while customers cannot pay","summary":"The pay endpoint answers 200 with an error message in the body when the provider fails, so clients, dashboards and alerts all see success.","category":"errors","difficulty":"beginner","skills":["http-status-codes","error-handling","observability"],"requires":["slot:payments.router.errors","svc:payments-stub"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"payments.router.errors","value":"from fastapi.responses import JSONResponse\n\ntry:\n    payment = await service.pay_order(session, client, customer.id, order_id)\nexcept service.OrderNotFound:\n    raise HTTPException(status_code=404, detail=\"order not found\") from None\nexcept service.OrderNotPayable:\n    raise HTTPException(status_code=409, detail=\"order cannot be paid\") from None\nexcept PaymentDeclined:\n    return JSONResponse(status_code=200, content={\"status\": \"error\", \"detail\": \"card declined\"})\nexcept PaymentTimeout:\n    return JSONResponse(status_code=200, content={\"status\": \"error\", \"detail\": \"payments provider timed out\"})\nexcept (PaymentUnavailable, PaymentError):\n    return JSONResponse(status_code=200, content={\"status\": \"error\", \"detail\": \"payments provider unavailable\"})\n"}]},"fix":{"slots":[{"slot":"payments.router.errors","value":"try:\n    payment = await service.pay_order(session, client, customer.id, order_id)\nexcept service.OrderNotFound:\n    raise HTTPException(status_code=404, detail=\"order not found\") from None\nexcept service.OrderNotPayable:\n    raise HTTPException(status_code=409, detail=\"order cannot be paid\") from None\nexcept PaymentDeclined:\n    raise HTTPException(status_code=402, detail=\"card declined\") from None\nexcept PaymentTimeout:\n    raise HTTPException(status_code=504, detail=\"payments provider timed out\") from None\nexcept (PaymentUnavailable, PaymentError):\n    raise HTTPException(status_code=502, detail=\"payments provider unavailable\") from None\n"}],"files":[{"path":"tests/test_payment_errors.py","from":"fix/tests/test_payment_errors.py"}]},"cheats":[{"name":"one-status-for-everything","slots":[{"slot":"payments.router.errors","value":"try:\n    payment = await service.pay_order(session, client, customer.id, order_id)\nexcept service.OrderNotFound:\n    raise HTTPException(status_code=404, detail=\"order not found\") from None\nexcept service.OrderNotPayable:\n    raise HTTPException(status_code=409, detail=\"order cannot be paid\") from None\nexcept (PaymentDeclined, PaymentTimeout, PaymentUnavailable, PaymentError):\n    raise HTTPException(status_code=502, detail=\"payment failed\") from None\n"}]},{"name":"revert-the-commit","slots":[{"slot":"payments.router.errors","value":"try:\n    payment = await service.pay_order(session, client, customer.id, order_id)\nexcept service.OrderNotFound:\n    raise HTTPException(status_code=404, detail=\"order not found\") from None\nexcept service.OrderNotPayable:\n    raise HTTPException(status_code=409, detail=\"order cannot be paid\") from None\nexcept PaymentDeclined:\n    raise HTTPException(status_code=402, detail=\"card declined\") from None\nexcept PaymentTimeout:\n    raise HTTPException(status_code=504, detail=\"payments provider timed out\") from None\nexcept (PaymentUnavailable, PaymentError):\n    raise HTTPException(status_code=502, detail=\"payments provider unavailable\") from None\n"}],"files":[{"path":"app/ext/stock_alerts.py","from":"cheats/empty_ext.py"}]}],"carrier":{"feature":"stock-alerts","files":[{"path":"app/ext/stock_alerts.py","from":"carrier/app/ext/stock_alerts.py"}]},"commit":{"message":"payments: friendlier payment errors for the mobile app, plus the low-stock alerts endpoint","persona":"Nayan Jaiswal \u003csam@shop.mindforge.test\u003e"},"checks":[{"ref":"check.http-behavior","role":"symptom","params":{"steps":[{"body":{"items":[{"product_id":3,"quantity":1}],"shipping_name":"ERR1-provider-down"},"expect_status":201,"headers":{"Authorization":"Bearer mf_tok_alice"},"method":"POST","path":"/api/v1/orders","save":{"order_id":"id"}},{"expect_status":[402,502,504],"headers":{"Authorization":"Bearer mf_tok_alice"},"method":"POST","path":"/api/v1/orders/{{order_id}}/pay","timeout":20}]}},{"ref":"check.pytest-node","role":"symptom","params":{"paths":["tests/fa_err_1/test_payment_errors.py"]}}],"symptom":{"vars":{"expected":"A failed payment must be visible as a failed request: a decline as 402, a provider timeout as 504 and an unreachable provider as 502, so that\nclients, retries, dashboards and alerts all behave correctly.","observations":"### Other observations from the reporter\n\n- The mobile app shows the generic failure screen only when the HTTP status is an error, so some customers saw a success screen and no receipt.\n- The change that made payment errors \"friendlier\" shipped together with the low-stock alerts endpoint.\n- The orders themselves stayed `pending`, nothing was charged twice.","report":"Support is flooded with customers saying that paying fails (\"payment error, try again\") and that they were not charged. The error-rate dashboard\nand the on-call alerts for the pay endpoint show 0 percent errors for the same period, so nobody was paged.","support_tried":"Compared access logs with the dashboards: every pay request in the bad hour is logged with status 200. The response bodies of the failures contain an\nerror message.","title":"Customers cannot pay, but the dashboards show zero payment errors","where":"`POST /api/v1/orders/{id}/pay`. The provider had a bad hour; the endpoint itself looks healthy from the outside."},"signature":"pay endpoint answers 200 with a JSON body whose status is error"},"hints":["Reproduce a provider failure (the lab runs the payments stub slow, or use its fault API) and call the pay endpoint with `curl -i`. What status line comes back, and what is in the body?","Status codes are part of the contract: load balancers, retries, SDKs and alerts key off them, not off the body. Look at how `pay` in `app/payments/router.py` handles `PaymentDeclined`, `PaymentTimeout` and `PaymentUnavailable`, and compare with how it handles `OrderNotFound`.","Raise `HTTPException` with the matching status (402, 504, 502) for each failure instead of returning a 200 JSON body, and add a test that fakes each provider failure and asserts the status code and that the order stays pending."],"rubric":{"key_points":["Explains that clients and monitoring decide success from the status code, so errors returned with 200 are invisible.","Maps each failure to its own meaningful status (402 decline, 504 provider timeout, 502 provider unavailable) rather than one for all.","Keeps a helpful message in the body without changing the status.","Adds tests that fake each provider failure and assert the status code."],"misconceptions":["A friendly 200 with an error flag is a harmless convention (it breaks retries, alerts and generic client handling).","Returning a single 500 or 502 for everything is equivalent (a decline is not a server error).","Fixing the dashboard query is the fix."]},"root_cause":"The `pay` handler caught the payment exceptions and returned `JSONResponse(status_code=200, content={\"status\": \"error\", ...})`. The failure was only visible in the body, so the access logs, the error-rate dashboard, the alert rules and the mobile app's status-based error handling all saw a successful request.\n\nThe fix raises `HTTPException` with the status that matches each failure: 402 for a decline, 504 when the provider times out and 502 when it cannot be reached. The detail message stays in the body for humans."}}$mf281e3a0b$::jsonb, 'lab-bundles/dde36add5afbc114c8a85546a5a63667e0f9ff0117adbfe025a5ec48e4c1343b.tar.gz', 'dde36add5afbc114c8a85546a5a63667e0f9ff0117adbfe025a5ec48e4c1343b', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

-- fa.mig.divergent-heads@1.0.0
