INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('7f4707a2-1c83-5c77-9c17-3daf6d0ddf6e', 'c7f907d5-f351-5da8-8f0c-902d64ca53c4', '1.0.0', 'adbbcd30ae0220411ac43eae75e142da5100b530dc98ce8761d877700512ae77', $mfadbbcd30${"kind":"app","id":"fa.orders","version":"1.0.0","stack":"fastapi","title":"Orders service (FastAPI)","summary":"Catalog, orders, a customer wallet, payments through an external provider, feature flags, staff reports, search and webhooks on FastAPI + async SQLAlchemy 2 + Alembic + PostgreSQL.","category":"app","difficulty":"","skills":["fastapi","sqlalchemy","alembic","postgres"],"requires":["svc:payments-stub"],"provides":["cap:postgres","cap:alembic","cap:async-sqlalchemy"],"budget":{"setup_seconds":5,"workspace_bytes":200000,"grader_bytes":120000},"app":{"language":"python","slots":[{"name":"customers.security.verify","type":"region","description":"Password verification (bcrypt is CPU-bound and runs in the thread pool)."},{"name":"db.session.dependency","type":"region","description":"The per-request session dependency body (open, yield, close)."},{"name":"flags.service.lookup","type":"region","description":"Reading one feature flag from the database."},{"name":"main.app.factory","type":"region","description":"Construction of the FastAPI application object (docs and OpenAPI settings)."},{"name":"orders.service.get_one","type":"region","description":"Fetching one order for the signed-in customer (ownership filter and eager loading)."},{"name":"orders.service.list_for_customer","type":"region","description":"The signed-in customer's order list query with its eager loading of items and products."},{"name":"payments.client.headers","type":"region","description":"Request headers of a charge call (idempotency key)."},{"name":"payments.client.http_client","type":"region","description":"Construction of the shared httpx client for the payments provider (base URL, timeouts)."},{"name":"payments.router.errors","type":"region","description":"Mapping of payment errors to HTTP responses in the pay endpoint."},{"name":"profile.service.changes","type":"region","description":"The set of fields a profile update applies (partial-update semantics)."},{"name":"wallet.service.apply_credit","type":"region","description":"Adding store credit to the balance (the read-modify-write of the balance)."}],"history":[{"message":"orders: place orders with atomic stock reservation and an order history endpoint","persona":"Nayan Jaiswal \u003cpriya@shop.mindforge.test\u003e","feature":"orders","paths":["orders"]},{"message":"wallet: store credit with a transaction ledger","persona":"Nayan Jaiswal \u003cmarcus@shop.mindforge.test\u003e","feature":"wallet","paths":["wallet"]},{"message":"payments: charge orders through the payments provider with retries and idempotency keys","persona":"Nayan Jaiswal \u003cpriya@shop.mindforge.test\u003e","feature":"payments","paths":["payments"]},{"message":"flags: staff-managed feature flags","persona":"Nayan Jaiswal \u003csam@shop.mindforge.test\u003e","feature":"flags","paths":["flags"]},{"message":"profile: partial profile updates","persona":"Nayan Jaiswal \u003celena@shop.mindforge.test\u003e","feature":"profile","paths":["profile"]},{"message":"search: product search by name and SKU","persona":"Nayan Jaiswal \u003cmarcus@shop.mindforge.test\u003e","feature":"search","paths":["search"]},{"message":"stock: staff stock adjustments that never go negative","persona":"Nayan Jaiswal \u003csam@shop.mindforge.test\u003e","feature":"stock","paths":["stock"]},{"message":"reports: paid orders and revenue per day for staff","persona":"Nayan Jaiswal \u003celena@shop.mindforge.test\u003e","feature":"reports","paths":["reports"]},{"message":"webhooks: signed payment events from the provider","persona":"Nayan Jaiswal \u003csam@shop.mindforge.test\u003e","feature":"webhooks","paths":["webhooks"]}],"noise":[{"message":"docs: describe the project layout in the README","persona":"Nayan Jaiswal \u003celena@shop.mindforge.test\u003e","paths":["docs-readme"]},{"message":"docs: add an operations runbook","persona":"Nayan Jaiswal \u003csam@shop.mindforge.test\u003e","paths":["docs-runbook"]},{"message":"deps: group requirements by purpose","persona":"Nayan Jaiswal \u003cmarcus@shop.mindforge.test\u003e","paths":["deps-grouping"]},{"message":"chore: ignore log files and virtualenvs","persona":"Nayan Jaiswal \u003cpriya@shop.mindforge.test\u003e","paths":["gitignore-logs"]}],"services":["postgres"],"ports":[8000],"protected":["pytest.ini","app/testing.py","tests/test_smoke.py"],"features":["orders","wallet","payments","flags","profile","search","stock","reports","webhooks","order-export","stock-alerts","customs-export","order-timeline","product-feed","account-overview"],"setup":["bash scripts/bootstrap.sh"],"readiness_path":"/healthz","test_globs":["tests/*","*/test_*.py","test_*.py"]}}$mfadbbcd30$::jsonb, 'lab-bundles/20858c3774796960a4e47a53b5718d29c8b48829791c93eb85530f4e36ad6391.tar.gz', '20858c3774796960a4e47a53b5718d29c8b48829791c93eb85530f4e36ad6391', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

-- fa.perf.order-list-n-plus-one@1.0.0
INSERT INTO public.lab_blocks (id, org_id, block_key, kind, stack)
VALUES ('72a316ec-dd2a-53a5-9b4c-481daf38614d', NULL, 'fa.perf.order-list-n-plus-one', 'fault', 'fastapi')
