  END IF;
  IF EXISTS (SELECT 1 FROM public.lab_block_versions WHERE block_id = 'e35851ad-07fa-57f2-a574-5480ce211129' AND version = '1.0.0' AND content_hash <> '1740bd3ea9c688e858d2e7d7122e0ee0c3197b1c57afd5d66de815270eb9bfc3') THEN
    RAISE EXCEPTION 'lab block % version % is already published with different content; bump the version', 'fs.api.search-query-not-encoded', '1.0.0';
  END IF;
END $mf1740bd3e$;
INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('034adb8a-31fd-5662-a658-5c2bb0b4f93d', 'e35851ad-07fa-57f2-a574-5480ce211129', '1.0.0', '1740bd3ea9c688e858d2e7d7122e0ee0c3197b1c57afd5d66de815270eb9bfc3', $mf1740bd3e${"kind":"fault","id":"fs.api.search-query-not-encoded","version":"1.0.0","stack":"fullstack","title":"Searching for \"R\u0026D Kit\" finds the wrong products","summary":"The catalog search puts the typed text into the URL without encoding it, so an ampersand ends the q parameter and the API only receives the text before it.","category":"api","difficulty":"beginner","skills":["url-encoding","query-strings","fetch"],"requires":["slot:catalog.search.request","cap:vitest","cap:fastapi-backend"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"catalog.search.request","value":"return get(`/api/products?q=${query}`, { signal });\n"}]},"fix":{"slots":[{"slot":"catalog.search.request","value":"return get(`/api/products?q=${encodeURIComponent(query)}`, { signal });\n"}],"files":[{"path":"tests/catalog-search-url.test.jsx","from":"fix/tests/catalog-search-url.test.jsx"},{"path":"backend/tests/test_search_api.py","from":"fix/tests/test_search_api.py"}]},"cheats":[{"name":"encode-only-ampersands","slots":[{"slot":"catalog.search.request","value":"return get(`/api/products?q=${query.replace(/\u0026/g, '%26')}`, { signal });\n"}]},{"name":"revert-the-commit","slots":[{"slot":"catalog.search.request","value":"return get(`/api/products?q=${encodeURIComponent(query)}`, { signal });\n"}],"files":[{"path":"backend/app/ext/low_stock.py","from":"cheats/empty_ext.py"}]}],"carrier":{"feature":"low-stock","files":[{"path":"backend/app/ext/low_stock.py","from":"carrier/backend/app/ext/low_stock.py"}]},"commit":{"message":"catalog: build the search URL directly and add the low-stock report","persona":"Nayan Jaiswal \u003celena@shop.mindforge.test\u003e"},"checks":[{"ref":"check.vitest-node","role":"symptom","params":{"paths":["tests/fs_api_1/search.test.jsx"]}},{"ref":"check.pytest-node","role":"symptom","params":{"paths":["tests/fs_api_1/test_search_api.py"]}}],"symptom":{"vars":{"expected":"The list contains exactly the products whose name or SKU contains the typed text.","observations":"### Other observations from QA\n\n- Plain words such as \"mouse\" or \"keyboard\" are found correctly.\n- The browser network tab shows the request as `/api/products?q=R\u0026D Kit`.\n- The low-stock report shipped in the same release as the catalog change.","report":"A buyer typed \"R\u0026D Kit\" into the catalog search and got a list of every product containing the letter R instead of the one kit\nthey wanted. Searches that contain a plus sign behave strangely too.","support_tried":"Searched for \"R\u0026D Kit\" directly through the API with curl (encoded) and the single kit came back, so we thought the data was fine.","title":"Searching for \"R\u0026D Kit\" lists everything containing an R","where":"The Catalog page, search box and Search button."},"signature":"the search request URL contains the raw typed text"},"hints":["Search for a plain word, then for \"R\u0026D Kit\", and compare the request URL in the network tab with what you typed.","A query string is `key=value\u0026key=value`. Text that contains `\u0026`, `+`, `#` or `%` means something else once it is inside a URL. Read how searchProducts builds its URL.","Encode the value with encodeURIComponent at the one place that builds the URL (not with a replace for one character). Add a test that asserts the exact URL for `\u0026`, `+`, `#` and `%`."],"rubric":{"key_points":["Reads the request URL and sees that `\u0026` split the typed text into a second parameter, so the API only got the text before it.","Notes that the API is correct (an encoded query finds the exact product) and the defect is the client building the URL.","Fixes it with encodeURIComponent at the single place the URL is built, not by replacing one character.","Tests the exact URL for several reserved characters."],"misconceptions":["The backend search is wrong (it matches an encoded query correctly).","Replacing `\u0026` is enough (`+`, `#` and `%` break the same way).","Encoding the whole URL instead of the value."]},"root_cause":"`searchProducts` interpolated the typed text straight into the URL (`/api/products?q=${query}`). An `\u0026` therefore started a new\nparameter and the API received `q=R`; `+` became a space and `#` cut the URL. The earlier code wrapped the value in\n`encodeURIComponent`; a refactor to build the URL directly dropped it.\n\nThe API was never at fault: `q=R%26D%20Kit` returns exactly the \"R\u0026D Kit\" product. The fix is `encodeURIComponent(query)` where\nthe URL is built, plus tests that assert the exact URL for the reserved characters."}}$mf1740bd3e$::jsonb, 'lab-bundles/7260f0083281be347eb4e403f61272eb125ea48a450dd5fa42cc7948584b55d0.tar.gz', '7260f0083281be347eb4e403f61272eb125ea48a450dd5fa42cc7948584b55d0', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

-- fs.auth.cookie-path-narrow@1.0.0
INSERT INTO public.lab_blocks (id, org_id, block_key, kind, stack)
VALUES ('48634f9e-c269-5150-99e2-60071134d024', NULL, 'fs.auth.cookie-path-narrow', 'fault', 'fullstack')
ON CONFLICT (org_id, block_key) DO NOTHING;
DO $mfdbd0f680$ BEGIN
  IF EXISTS (SELECT 1 FROM public.lab_blocks WHERE id = '48634f9e-c269-5150-99e2-60071134d024' AND (kind <> 'fault' OR stack <> 'fullstack')) THEN
    RAISE EXCEPTION 'lab block % changed kind or stack; block identity is immutable', 'fs.auth.cookie-path-narrow';
  END IF;
  IF EXISTS (SELECT 1 FROM public.lab_block_versions WHERE block_id = '48634f9e-c269-5150-99e2-60071134d024' AND version = '1.0.0' AND content_hash <> 'dbd0f68082e94d361048521fab9f073aeb880c3b940b103dbae2f18b1f1f2059') THEN
    RAISE EXCEPTION 'lab block % version % is already published with different content; bump the version', 'fs.auth.cookie-path-narrow', '1.0.0';
  END IF;
END $mfdbd0f680$;
INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('daa16472-f51e-5641-b949-c5deef4f1907', '48634f9e-c269-5150-99e2-60071134d024', '1.0.0', 'dbd0f68082e94d361048521fab9f073aeb880c3b940b103dbae2f18b1f1f2059', $mfdbd0f680${"kind":"fault","id":"fs.auth.cookie-path-narrow","version":"1.0.0","stack":"fullstack","title":"Signed in, but every page says the session expired","summary":"The session cookie is scoped to the auth routes, so the browser stops sending it to the orders, profile and other API paths right after login.","category":"auth","difficulty":"intermediate","skills":["cookies","sessions","http-headers"],"requires":["slot:auth.cookie.attrs","cap:fastapi-backend","cap:vitest"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"auth.cookie.attrs","value":"response.set_cookie(SESSION_COOKIE, token, httponly=True, samesite=\"lax\", path=\"/api/auth\")\n"}]},"fix":{"slots":[{"slot":"auth.cookie.attrs","value":"response.set_cookie(SESSION_COOKIE, token, httponly=True, samesite=\"lax\", path=\"/\")\n"}],"files":[{"path":"backend/tests/test_session_cookie.py","from":"fix/tests/test_session_cookie.py"},{"path":"tests/session-path.test.jsx","from":"fix/tests/session-path.test.jsx"}]},"cheats":[{"name":"orders-path-only","slots":[{"slot":"auth.cookie.attrs","value":"response.set_cookie(SESSION_COOKIE, token, httponly=True, samesite=\"lax\", path=\"/api/orders\")\n"}]},{"name":"drop-httponly","slots":[{"slot":"auth.cookie.attrs","value":"response.set_cookie(SESSION_COOKIE, token, httponly=False, samesite=\"lax\", path=\"/\")\n"}]},{"name":"revert-the-commit","slots":[{"slot":"auth.cookie.attrs","value":"response.set_cookie(SESSION_COOKIE, token, httponly=True, samesite=\"lax\", path=\"/\")\n"}],"files":[{"path":"src/ext/order-total/index.js","from":"cheats/empty-extension.js"}]}],"carrier":{"feature":"order-total","files":[{"path":"src/ext/order-total/index.js","from":"carrier/src/ext/order-total/index.js"}]},"commit":{"message":"auth: scope the session cookie and add a page total action to Orders","persona":"Nayan Jaiswal \u003cpriya@shop.mindforge.test\u003e"},"checks":[{"ref":"check.pytest-node","role":"symptom","params":{"paths":["tests/fs_cookie_path/test_session_cookie.py"]}},{"ref":"check.vitest-node","role":"symptom","params":{"paths":["tests/fs_cookie_path/session.test.jsx"]}}],"symptom":{"vars":{"expected":"After a successful sign-in every API request is authenticated until the customer signs out.","observations":"### Other observations from QA\n\n- In the browser's cookie view the session cookie exists after sign-in, but the network tab shows no Cookie header on the failing requests.\n- The \"who am I\" call at the top of the page still works.\n- The page total action in the Orders tools came in the same release as a change to the cookie settings.","report":"After the last release a customer signs in, sees the welcome page, and the moment they open Orders or Profile the console\nshows \"Sign in to continue.\" Signing in again gives the same result. Support can sign in and see the account name in the\nheader, but nothing that loads data works. Before the release the same accounts worked fine.","support_tried":"Cleared cookies, tried a private window and another browser. Same result, and the login request itself returns 200 with the user.","title":"Sign-in succeeds, then Orders and Profile say \"Sign in to continue\"","where":"Every screen that loads data after sign-in (orders, profile, checkout). Only the sign-in and the \"who am I\" call work."},"signature":"the session cookie is not sent to paths outside the auth routes"},"hints":["Sign in with curl using a cookie jar (-c / -b) and request /api/orders with it. Then request /api/auth/me. One works and the other does not, which is a hint about what the cookie is scoped to.","A cookie is only sent to URLs under its Path attribute. Read the Set-Cookie header of the login response and the `set_cookie` call in `backend/app/auth.py` (`git log -p` shows what the last release changed).","Set the session cookie Path to / (or at least /api), keeping HttpOnly and SameSite. Add a test that signs in and then calls a non-auth endpoint through a client that honours cookie paths."],"rubric":{"key_points":["Identifies that the cookie Path attribute limits which request URLs carry the cookie, and that /api/auth excluded the data endpoints.","Explains why the login response and the auth routes still worked while everything else answered 401.","Fixes the attribute at the set_cookie call (Path=/ or /api) and keeps HttpOnly and SameSite intact.","Adds a test that exercises a non-auth endpoint after login with real cookie-path matching, not a hand-built Cookie header."],"misconceptions":["The session was not created or expired (the server created it and the browser simply did not send the cookie).","Removing HttpOnly or sending the session in a header is a fix (it weakens the design and leaves the Path wrong).","Setting a path that covers only the failing endpoint is enough (every other endpoint stays broken)."]},"root_cause":"The login handler set the session cookie with `path=\"/api/auth\"`. Browsers send a cookie only to URLs whose path falls under the\ncookie's Path, so the session cookie reached `/api/auth/me` and `/api/auth/logout` but was left out of `/api/orders`,\n`/api/profile` and every other data endpoint. Those endpoints saw no session and answered 401 not_authenticated, even though\nlogin had just succeeded.\n\nThe fix scopes the cookie to `/` again. The test goes through a client that applies cookie path matching, so it fails when the\npath excludes an endpoint (a hand-built Cookie header would hide the bug)."}}$mfdbd0f680$::jsonb, 'lab-bundles/803df4996ff18db69776f7fbd470865914288b6698f52acabf631c5f98038a3d.tar.gz', '803df4996ff18db69776f7fbd470865914288b6698f52acabf631c5f98038a3d', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

-- fs.auth.csrf-cookie-httponly@1.0.0
INSERT INTO public.lab_blocks (id, org_id, block_key, kind, stack)
VALUES ('90f9870d-b245-558b-a9dd-8300a3fb80cb', NULL, 'fs.auth.csrf-cookie-httponly', 'fault', 'fullstack')
ON CONFLICT (org_id, block_key) DO NOTHING;
DO $mf7dff571c$ BEGIN
  IF EXISTS (SELECT 1 FROM public.lab_blocks WHERE id = '90f9870d-b245-558b-a9dd-8300a3fb80cb' AND (kind <> 'fault' OR stack <> 'fullstack')) THEN
    RAISE EXCEPTION 'lab block % changed kind or stack; block identity is immutable', 'fs.auth.csrf-cookie-httponly';
  END IF;
  IF EXISTS (SELECT 1 FROM public.lab_block_versions WHERE block_id = '90f9870d-b245-558b-a9dd-8300a3fb80cb' AND version = '1.0.0' AND content_hash <> '7dff571cb9f5074e18f8cb422d2829ad9dbde58c0d630a201651790411d64799') THEN
    RAISE EXCEPTION 'lab block % version % is already published with different content; bump the version', 'fs.auth.csrf-cookie-httponly', '1.0.0';
  END IF;
END $mf7dff571c$;
INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('0fe2ed52-7966-5c00-b578-d866322a942a', '90f9870d-b245-558b-a9dd-8300a3fb80cb', '1.0.0', '7dff571cb9f5074e18f8cb422d2829ad9dbde58c0d630a201651790411d64799', $mf7dff571c${"kind":"fault","id":"fs.auth.csrf-cookie-httponly","version":"1.0.0","stack":"fullstack","title":"Every save is rejected as \"could not be verified\" after the cookie hardening","summary":"The CSRF cookie was made HttpOnly, so the page script can no longer read it, the client sends an empty token and the API answers 403 csrf_failed to every write.","category":"auth","difficulty":"intermediate","skills":["csrf","cookies","security-headers"],"requires":["slot:auth.csrf.cookie","cap:fastapi-backend","cap:vitest"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"auth.csrf.cookie","value":"response.set_cookie(CSRF_COOKIE, csrf, httponly=True, samesite=\"lax\", path=\"/\")\n"}]},"fix":{"slots":[{"slot":"auth.csrf.cookie","value":"response.set_cookie(CSRF_COOKIE, csrf, httponly=False, samesite=\"lax\", path=\"/\")\n"}],"files":[{"path":"backend/tests/test_csrf_cookie.py","from":"fix/tests/test_csrf_cookie.py"},{"path":"tests/csrf-cookie.test.jsx","from":"fix/tests/csrf-cookie.test.jsx"}]},"cheats":[{"name":"both-cookies-readable","slots":[{"slot":"auth.cookie.attrs","value":"response.set_cookie(SESSION_COOKIE, token, httponly=False, samesite=\"lax\", path=\"/\")\n"},{"slot":"auth.csrf.cookie","value":"response.set_cookie(CSRF_COOKIE, csrf, httponly=False, samesite=\"lax\", path=\"/\")\n"}]},{"name":"revert-the-commit","slots":[{"slot":"auth.csrf.cookie","value":"response.set_cookie(CSRF_COOKIE, csrf, httponly=False, samesite=\"lax\", path=\"/\")\n"}],"files":[{"path":"src/ext/status-breakdown/index.js","from":"cheats/empty-extension.js"}]}],"carrier":{"feature":"status-breakdown","files":[{"path":"src/ext/status-breakdown/index.js","from":"carrier/src/ext/status-breakdown/index.js"}]},"commit":{"message":"auth: harden the login cookies and add a status breakdown action to Orders","persona":"Nayan Jaiswal \u003crahul@shop.mindforge.test\u003e"},"checks":[{"ref":"check.pytest-node","role":"symptom","params":{"paths":["tests/fs_csrf_cookie/test_csrf_cookie.py"]}},{"ref":"check.vitest-node","role":"symptom","params":{"paths":["tests/fs_csrf_cookie/csrf.test.jsx"]}}],"symptom":{"vars":{"expected":"A signed-in customer can save their profile and place orders.","observations":"### Other observations from QA\n\n- The API answers 403 with code `csrf_failed`; the failing requests have an empty `X-CSRF-Token` header.\n- The browser's cookie view shows a `csrf_token` cookie after sign-in, but `document.cookie` in the console does not list it.\n- The status breakdown action in the Orders tools shipped in the same release as the cookie hardening.","report":"Since the security hardening release nobody can save: the profile form, placing an order and signing out all show \"The request\ncould not be verified. Reload the page and try again.\" Reloading and signing in again does not help. Browsing, searching and\nreading orders work normally, and the session itself is fine.","support_tried":"Cleared cookies, signed in again and tried another browser. Same message everywhere, so it is not one broken session.","title":"Saving anything fails with \"The request could not be verified\"","where":"Every action that changes data - saving the profile, checkout, logout."},"signature":"document.cookie does not contain csrf_token, so writes carry an empty token"},"hints":["Open the browser console after signing in and run document.cookie. Compare it with the cookie list in the storage inspector. Which cookie is missing from the script's view, and what makes a cookie invisible to scripts?","The API uses a double-submit token. The API client reads the csrf_token cookie and echoes it in a header, which only works if the cookie is not HttpOnly. Read the two `set_cookie` calls in `backend/app/auth.py`, and `git log -p` for the change.","Keep the session cookie HttpOnly but make the CSRF cookie readable (httponly=False); the token is not a secret from the page, it only has to be unknown to other sites. Add a test for the Set-Cookie flags of both cookies and one that does a write through the real client."],"rubric":{"key_points":["Identifies how the double-submit CSRF pattern works and that the token cookie has to be readable by the page script.","Explains why HttpOnly on the CSRF cookie produced an empty header and therefore 403 csrf_failed, while reads kept working.","Fixes only the CSRF cookie flag and keeps the session cookie HttpOnly (does not weaken both for convenience).","Tests the Set-Cookie flags of both cookies and a successful write through the client."],"misconceptions":["HttpOnly should be on every cookie (it protects the session, but the CSRF cookie must be read by the page by design).","Making the session cookie readable as well is a fine fix (it exposes the session to XSS).","Disabling CSRF validation or accepting an empty token removes the symptom (it removes the protection)."]},"root_cause":"The login handler set the `csrf_token` cookie with `httponly=True` as part of a cookie-hardening change. The API's CSRF protection is\na double-submit token: the client reads the cookie and echoes the value in `X-CSRF-Token`. With HttpOnly the page script cannot see\nthe cookie, `readCookie` returned an empty string, and the server rejected every state-changing request with 403 `csrf_failed`\nwhile GET requests (which are not checked) kept working.\n\nThe fix makes only the CSRF cookie script-readable again (`httponly=False`); the session cookie stays HttpOnly. The tests check\nboth cookies' flags and a profile save through the real API client."}}$mf7dff571c$::jsonb, 'lab-bundles/d7da2e1a14c95f6d667c3f882eafb1a637a3ef405a721cb45d54868bbd74cfda.tar.gz', 'd7da2e1a14c95f6d667c3f882eafb1a637a3ef405a721cb45d54868bbd74cfda', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

-- fs.cors.credentials-disabled@1.0.0
INSERT INTO public.lab_blocks (id, org_id, block_key, kind, stack)
VALUES ('21add9b0-19bf-54ff-8812-8871868bd35a', NULL, 'fs.cors.credentials-disabled', 'fault', 'fullstack')
ON CONFLICT (org_id, block_key) DO NOTHING;
DO $mfdcd10037$ BEGIN
