INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('220c5a09-55b1-59de-ad8e-bb27fd865ffd', '21add9b0-19bf-54ff-8812-8871868bd35a', '1.0.0', 'dcd10037ca8734a479f6cec206b66d0e2bdbe8ab4aee0a301a5c13bbd3a7ab7a', $mfdcd10037${"kind":"fault","id":"fs.cors.credentials-disabled","version":"1.0.0","stack":"fullstack","title":"Sign-in works in curl but the browser never keeps the session","summary":"The CORS middleware stopped allowing credentials, so the browser refuses cross-origin responses from the API and the session cookie is never stored or sent.","category":"cors","difficulty":"intermediate","skills":["cors","cookies","http-headers"],"requires":["slot:api.cors.config","cap:fastapi-backend","cap:vitest"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"api.cors.config","value":"app.add_middleware(\n    CORSMiddleware,\n    allow_origins=settings.allowed_origins,\n    allow_credentials=False,\n    allow_methods=[\"GET\", \"POST\", \"PUT\", \"DELETE\"],\n    allow_headers=[\"Content-Type\", \"X-CSRF-Token\"],\n)\n"}]},"fix":{"slots":[{"slot":"api.cors.config","value":"app.add_middleware(\n    CORSMiddleware,\n    allow_origins=settings.allowed_origins,\n    allow_credentials=True,\n    allow_methods=[\"GET\", \"POST\", \"PUT\", \"DELETE\"],\n    allow_headers=[\"Content-Type\", \"X-CSRF-Token\"],\n)\n"}],"files":[{"path":"backend/tests/test_cors_credentials.py","from":"fix/tests/test_cors_credentials.py"}]},"cheats":[{"name":"pinned-dev-origin","slots":[{"slot":"api.cors.config","value":"app.add_middleware(\n    CORSMiddleware,\n    allow_origins=[\"http://localhost:5173\"],\n    allow_credentials=True,\n    allow_methods=[\"GET\", \"POST\", \"PUT\", \"DELETE\"],\n    allow_headers=[\"Content-Type\", \"X-CSRF-Token\"],\n)\n"}]},{"name":"reflect-any-origin","slots":[{"slot":"api.cors.config","value":"app.add_middleware(\n    CORSMiddleware,\n    allow_origin_regex=\".*\",\n    allow_credentials=True,\n    allow_methods=[\"GET\", \"POST\", \"PUT\", \"DELETE\"],\n    allow_headers=[\"Content-Type\", \"X-CSRF-Token\"],\n)\n"}]},{"name":"revert-the-commit","slots":[{"slot":"api.cors.config","value":"app.add_middleware(\n    CORSMiddleware,\n    allow_origins=settings.allowed_origins,\n    allow_credentials=True,\n    allow_methods=[\"GET\", \"POST\", \"PUT\", \"DELETE\"],\n    allow_headers=[\"Content-Type\", \"X-CSRF-Token\"],\n)\n"}],"files":[{"path":"backend/app/ext/low_stock.py","from":"cheats/empty_ext.py"}]}],"carrier":{"feature":"low-stock","files":[{"path":"backend/app/ext/low_stock.py","from":"carrier/backend/app/ext/low_stock.py"}]},"commit":{"message":"reports: add the low-stock report and tidy the CORS setup","persona":"Nayan Jaiswal \u003csam@shop.mindforge.test\u003e"},"checks":[{"ref":"check.pytest-node","role":"symptom","params":{"paths":["tests/fs_cors/test_cors_credentials.py"]}},{"ref":"check.vitest-node","role":"symptom","params":{"paths":["tests/fs_cors/cors.test.jsx"]}}],"symptom":{"vars":{"expected":"Signing in works cross-origin and the session cookie is kept and sent on every later request.","observations":"### Other observations from QA\n\n- The response carries `access-control-allow-origin` with the staging origin, so the origin list itself is not the problem.\n- The new low-stock report came in the same release as a clean-up of the middleware setup.\n- The network tab shows the preflight succeeding and the actual request being blocked by the browser, not rejected by the server.","report":"On the staging console (a different host than the API) nobody can sign in any more. The form shows \"Failed to fetch\" after\na second, and the browser console prints a CORS error about the credentials mode. The API itself is fine: curl and the\nSwagger page log in without any problem. On a developer machine, where the page and the API share one origin through the\nVite proxy, it still works.","support_tried":"Checked that the staging origin is listed in SHOP_ALLOWED_ORIGINS and restarted the API. The list is correct and the error did not change.","title":"Staging console cannot sign in - the form just says \"Failed to fetch\"","where":"Any browser session where the console is served from another origin than the API (staging, preview deploys)."},"signature":"a credentialed cross-origin request is refused by the browser"},"hints":["Reproduce it like a browser would, with an Origin header (curl -i -H, then read the response headers of /api/health) and compare the response headers with a working setup. Which CORS header is missing?","A fetch with credentials set to include is only accepted when the response says Access-Control-Allow-Credentials true and names the exact origin (a wildcard is not allowed). Read the CORS block in `backend/app/main.py` and `git log -p` for what the last release changed there.","Set `allow_credentials=True` and keep the explicit origin list from the settings (do not hardcode one environment, and do not reflect every origin). Add a test that sends an Origin header and checks both the origin and the credentials header, plus one for an origin that must stay refused."],"rubric":{"key_points":["Identifies that the browser requires Access-Control-Allow-Credentials true (and a non-wildcard origin) for a credentialed cross-origin request, and that the middleware dropped it.","Explains why curl and same-origin dev (Vite proxy) were not affected.","Restores allow_credentials=True while keeping the configured origin list, rather than hardcoding an origin or reflecting any origin.","Tests the response headers for an allowed origin and that an unknown origin is still refused."],"misconceptions":["Adding the origin to the allowed list fixes it (it was already allowed; the credentials header was missing).","A wildcard origin is a fine fix (browsers refuse a wildcard for credentialed requests, and it would open the API to every site).","The cookie attributes are wrong (the cookie is fine; the browser never got to store it)."]},"root_cause":"A clean-up of the CORS setup in `create_app` set `allow_credentials=False`. The API therefore answered cross-origin requests\nwithout `Access-Control-Allow-Credentials: true`. A browser refuses to expose a response to a page that asked for credentials\nunless that header is present, so the login response was dropped (the cookie was never stored) and `fetch` rejected with \"Failed\nto fetch\". curl does not enforce CORS and the Vite dev proxy makes the console same-origin, which is why only deployed\nenvironments broke.\n\nThe fix sets `allow_credentials=True` next to the explicit origins from `SHOP_ALLOWED_ORIGINS`. The test sends an Origin header\nand checks the reflected origin, the credentials header and that an unlisted origin is not allowed."}}$mfdcd10037$::jsonb, 'lab-bundles/8e4a34ae75706340775010db956fceb7fc19e5984609213415c8b416ea97d602.tar.gz', '8e4a34ae75706340775010db956fceb7fc19e5984609213415c8b416ea97d602', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

-- fs.csrf.wrong-cookie-name@1.0.0
