  IF EXISTS (SELECT 1 FROM public.lab_blocks WHERE id = 'b225984b-8938-56be-9787-7df148f927ba' AND (kind <> 'fault' OR stack <> 'fullstack')) THEN
    RAISE EXCEPTION 'lab block % changed kind or stack; block identity is immutable', 'fs.csrf.wrong-cookie-name';
  END IF;
  IF EXISTS (SELECT 1 FROM public.lab_block_versions WHERE block_id = 'b225984b-8938-56be-9787-7df148f927ba' AND version = '1.0.0' AND content_hash <> 'dd2d2df4127210b31f38bccc1284acd3fa0fea33924f1ef9a86e2f46cdd80116') THEN
    RAISE EXCEPTION 'lab block % version % is already published with different content; bump the version', 'fs.csrf.wrong-cookie-name', '1.0.0';
