  END IF;
  IF EXISTS (SELECT 1 FROM public.lab_block_versions WHERE block_id = 'e3b7edbb-11af-5603-b0ee-7eb630ae16cb' AND version = '1.0.0' AND content_hash <> 'b5b8e28381849c0f6e139e04436251bf4e64d5f431d1f47f9cfc097ffce5cc50') THEN
    RAISE EXCEPTION 'lab block % version % is already published with different content; bump the version', 'fs.data.naive-placed-at', '1.0.0';
