  END IF;
  IF EXISTS (SELECT 1 FROM public.lab_block_versions WHERE block_id = 'b5aa34a7-9613-58f8-a9be-2e567810150e' AND version = '1.0.0' AND content_hash <> '228b555472063c76ff9b3943150835998083b095984838faa28224f417144aba') THEN
