INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('9e82d478-dc15-598e-9463-63abf5919151', '20fbc820-43d9-5c67-9539-0552e42e73e0', '1.0.0', '0ef46134c028457a0f6e7a21fa528fc034828139f2d78a1e8d1eb632cafd51a3', $mf0ef46134${"kind":"fault","id":"fs.err.detail-shaped-errors","version":"1.0.0","stack":"fullstack","title":"Not-found and forbidden errors in the console say only \"Request failed\"","summary":"The API error handler returns a FastAPI-style detail body for 403 and 404 errors instead of the error envelope the console reads, so screens lose their messages and error codes.","category":"api","difficulty":"beginner","skills":["error-handling","api-contracts","fastapi"],"requires":["slot:api.errors.handler","cap:fastapi-backend","cap:vitest"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"api.errors.handler","value":"@app.exception_handler(ApiError)\nasync def api_error_handler(_request, exc: ApiError):\n    if exc.status in (403, 404):\n        return JSONResponse(status_code=exc.status, content={\"detail\": exc.message})\n    return JSONResponse(status_code=exc.status, content=error_body(exc.code, exc.message))\n"}]},"fix":{"slots":[{"slot":"api.errors.handler","value":"@app.exception_handler(ApiError)\nasync def api_error_handler(_request, exc: ApiError):\n    return JSONResponse(status_code=exc.status, content=error_body(exc.code, exc.message))\n"}],"files":[{"path":"backend/tests/test_error_body.py","from":"fix/tests/test_error_body.py"},{"path":"tests/error-message.test.jsx","from":"fix/tests/error-message.test.jsx"}]},"cheats":[{"name":"error-as-string","slots":[{"slot":"api.errors.handler","value":"@app.exception_handler(ApiError)\nasync def api_error_handler(_request, exc: ApiError):\n    if exc.status in (403, 404):\n        return JSONResponse(status_code=exc.status, content={\"error\": exc.message})\n    return JSONResponse(status_code=exc.status, content=error_body(exc.code, exc.message))\n"}]},{"name":"message-without-code","slots":[{"slot":"api.errors.handler","value":"@app.exception_handler(ApiError)\nasync def api_error_handler(_request, exc: ApiError):\n    if exc.status in (403, 404):\n        return JSONResponse(status_code=exc.status, content={\"error\": {\"message\": exc.message}})\n    return JSONResponse(status_code=exc.status, content=error_body(exc.code, exc.message))\n"}]},{"name":"revert-the-commit","slots":[{"slot":"api.errors.handler","value":"@app.exception_handler(ApiError)\nasync def api_error_handler(_request, exc: ApiError):\n    return JSONResponse(status_code=exc.status, content=error_body(exc.code, exc.message))\n"}],"files":[{"path":"backend/app/ext/order_summary.py","from":"cheats/empty_ext.py"}]}],"carrier":{"feature":"order-summary","files":[{"path":"backend/app/ext/order_summary.py","from":"carrier/backend/app/ext/order_summary.py"}]},"commit":{"message":"reports: add the order summary report and use the framework error shape","persona":"Nayan Jaiswal \u003cmarcus@shop.mindforge.test\u003e"},"checks":[{"ref":"check.pytest-node","role":"symptom","params":{"paths":["tests/fs_errors/test_error_body.py"]}},{"ref":"check.vitest-node","role":"symptom","params":{"paths":["tests/fs_errors/errors.test.jsx"]}}],"symptom":{"vars":{"expected":"The user sees the API's own message for each failure, and screens can still branch on the error code.","observations":"### Other observations from QA\n\n- Sign-in failures (401), profile conflicts (409) and validation errors (422) still show their messages; only some errors lost theirs.\n- The network tab shows a response body of `{\"detail\": \"...\"}` for the 404 and 403 failures.\n- The order summary report was added in the same release, together with a tidy-up of the error handler.","report":"Since the last release some failures no longer explain themselves. Opening an order that does not exist used to say \"No such order.\"\nand a blocked request (403) used to say the request could not be verified. Now they just show \"Request failed\"\nfollowed by the status number (404, 403), and the screens that react to a specific error code stopped doing so.","support_tried":"Checked that the right status codes come back (404 for a missing order, 403 for a blocked request). The statuses are correct, only the text is missing.","title":"Missing-order and blocked-request errors show \"Request failed (404)\" instead of a message","where":"Screens that show a missing or forbidden request - order details, checkout with an unknown product, blocked actions."},"signature":"404/403 API errors have a {\"detail\"} body instead of {\"error\": {\"code\", \"message\"}}"},"hints":["Trigger a 404 with curl (an order id that does not exist) and read the raw body. Compare it with a wrong-password 401, which still shows its message in the console.","The console's API client reads `payload.error.message` and `payload.error.code`, and `backend/app/errors.py` has a helper that builds exactly that body. Look at which handler stopped using it (`git log -p backend/app/errors.py`).","Return `error_body(exc.code, exc.message)` from the ApiError handler for every status so the one envelope is built in one place. Add a backend test that pins the body shape (code and message) and a client test for the message the user sees."],"rubric":{"key_points":["Identifies the contract between the API (error envelope) and the client (`payload.error.message`/`code`) and that the handler broke it.","Notes that the status codes were right, so the client fell back to its generic message.","Fixes the single handler by reusing the shared `error_body` helper instead of adapting every screen or the client to a second shape.","Adds tests for the body shape on the API side and the visible message/code on the client side."],"misconceptions":["The client should also accept `detail` (it hides the contract break and every other consumer still gets two shapes).","Only the message matters (screens branch on the code, for example order_not_found).","Returning the message as a plain string under \"error\" is equivalent (the client reads error.message)."]},"root_cause":"The ApiError handler was changed to return `{\"detail\": message}`, the default FastAPI shape, for 403 and 404 errors, instead of `error_body(code, message)`.\nThe console's API client reads `payload.error.message` and `payload.error.code`; with a `detail` body both are undefined, so it\nfell back to \"Request failed (\u003cstatus\u003e)\" and lost the code that screens branch on. The status codes were still correct and 401/409/422 kept working, which\nmade the regression easy to miss.\n\nThe fix restores `error_body(...)` in the handler (one place builds the envelope for ApiError and for validation errors). The\nbackend test pins `{\"error\": {\"code\", \"message\"}}` and the client test checks the message and code a user-facing screen receives."}}$mf0ef46134$::jsonb, 'lab-bundles/ccb5aed4b67e8ab2526fb1c9e0bea312c3119a239d86c0f0c4aa20257f0892ea.tar.gz', 'ccb5aed4b67e8ab2526fb1c9e0bea312c3119a239d86c0f0c4aa20257f0892ea', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

