  END IF;
  IF EXISTS (SELECT 1 FROM public.lab_block_versions WHERE block_id = '16ab710e-914b-5aba-9bfa-0d6d1cc5247a' AND version = '1.0.0' AND content_hash <> '24668f7aabeb6b76edb79f93ce80a929c8b61461db992d3523c60d94c8bfb384') THEN
