INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('6f0a36a4-6ebc-51e9-b29b-0aa63cda4c79', '329ae53d-8d22-549c-9582-a19baf884578', '1.0.0', 'f7d21828974d3b88ff5cdd895785aace68cb93fce0f81f00a998c5ffa382584e', $mff7d21828${"kind":"fault","id":"fs.state.profile-version-ignored","version":"1.0.0","stack":"fullstack","title":"An old tab overwrites a newer profile","summary":"The optimistic-concurrency check only rejects versions from the future, so a save made from a stale tab silently overwrites newer changes.","category":"state","difficulty":"intermediate","skills":["optimistic-concurrency","http-status","state"],"requires":["slot:profile.update.version-check","cap:fastapi-backend","cap:vitest"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"profile.update.version-check","value":"if body.version \u003e user[\"version\"]:\n    raise ApiError(409, \"version_conflict\", \"The profile was changed elsewhere. Reload and try again.\")\n"}]},"fix":{"slots":[{"slot":"profile.update.version-check","value":"if body.version != user[\"version\"]:\n    raise ApiError(409, \"version_conflict\", \"The profile was changed elsewhere. Reload and try again.\")\n"}],"files":[{"path":"backend/tests/test_version_check.py","from":"fix/tests/test_version_check.py"}]},"cheats":[{"name":"only-the-first-version","slots":[{"slot":"profile.update.version-check","value":"if body.version != user[\"version\"] and (body.version == 1 or body.version \u003e user[\"version\"]):\n    raise ApiError(409, \"version_conflict\", \"The profile was changed elsewhere. Reload and try again.\")\n"}]},{"name":"reject-after-first-save","slots":[{"slot":"profile.update.version-check","value":"if user[\"version\"] \u003e 1 or body.version != user[\"version\"]:\n    raise ApiError(409, \"version_conflict\", \"The profile was changed elsewhere. Reload and try again.\")\n"}]},{"name":"revert-the-commit","slots":[{"slot":"profile.update.version-check","value":"if body.version != user[\"version\"]:\n    raise ApiError(409, \"version_conflict\", \"The profile was changed elsewhere. Reload and try again.\")\n"}],"files":[{"path":"backend/app/ext/low_stock.py","from":"cheats/empty_ext.py"}]}],"carrier":{"feature":"low-stock","files":[{"path":"backend/app/ext/low_stock.py","from":"carrier/backend/app/ext/low_stock.py"}]},"commit":{"message":"reports: add the low-stock report and allow profile saves from slightly older versions","persona":"Nayan Jaiswal \u003csam@shop.mindforge.test\u003e"},"checks":[{"ref":"check.pytest-node","role":"symptom","params":{"paths":["tests/fs_state_profile_version/test_version_check.py"]}},{"ref":"check.vitest-node","role":"symptom","params":{"paths":["tests/fs_state_profile_version/profile_conflict.test.jsx"]}}],"symptom":{"vars":{"expected":"A save based on an out-of-date profile is refused and the customer is told to reload, as before.","observations":"### Other observations from QA\n\n- The \"changed in another tab or device\" message used to appear in this situation.\n- Saving twice in a row from one tab works as expected.\n- The low-stock report came in the same release.","report":"A customer updated their phone number from the mobile site, then went back to a laptop tab that had been open since the\nmorning, fixed a typo in the name and pressed Save. The page said \"Profile saved\" and the new phone number was gone, replaced\nby the old one from the open tab. Two other customers described the same thing after using two devices.","support_tried":"Reproduced it with two browsers. The first save works; the save from the older tab also works and wins.","title":"Saving my profile on my laptop erased the phone number I just changed on my phone","where":"The profile page, when it is open in more than one tab or device."},"signature":"a save with a stale profile version returns 200 instead of 409 version_conflict"},"hints":["Open the profile in two tabs, save in one, then save in the other and look at the PUT request and its response status. What version does each request carry?","Every save carries the version it was based on, and the server must refuse any save whose version is not the current one. Read the check at the top of the profile update and check git log -p for the change that touched it.","Compare for equality (the request version must equal the stored version), not just for a larger number, in the one place that saves. Add a backend test with two saves from the same version and a frontend test that shows the conflict message."],"rubric":{"key_points":["Identifies that the check only rejects versions greater than the stored one, so stale (lower) versions pass.","Explains the lost update (a stale form overwrites newer data) and why 409 is the right response.","Fixes the check to require equality in the server, not in the UI.","Tests two saves from the same version and a version several saves behind."],"misconceptions":["Comparing in the frontend is enough (another client can still send a stale version).","Rejecting every save after the first one fixes it (it breaks normal sequential saves).","Only version 1 can be stale."]},"root_cause":"The version check in `update_profile` was loosened from `body.version != user[\"version\"]` to `body.version \u003e user[\"version\"]` so that\n\"slightly older versions\" could still save. A request based on an older profile has a smaller version, so it passed the check and\noverwrote the newer name and phone: a lost update. Only a version from the future was refused.\n\nOptimistic concurrency needs equality: the version the client saw must be the version in the store, otherwise the server answers\n409 `version_conflict` and the client asks the customer to reload. The backend tests cover a repeated version and a version several\nsaves behind; the frontend test shows the conflict message for a stale tab."}}$mff7d21828$::jsonb, 'lab-bundles/8a970e94d2be31d2173d9b2523a5d55d91ac8d1739695d260f1074edc2cd527d.tar.gz', '8a970e94d2be31d2173d9b2523a5d55d91ac8d1739695d260f1074edc2cd527d', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

-- re.api.calendar-day-off-by-one@1.0.0
