INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('bb492a31-e22e-5e71-b0ea-1847f9b118ed', '6dd26a41-e502-547f-8635-661931ab85f5', '1.0.0', 'cc294e4019d9671f4f86f75e1c9df56c4918c9415f9c868d79f5872ebc43d568', $mfcc294e40${"kind":"fault","id":"re.api.calendar-day-off-by-one","version":"1.0.0","stack":"react","title":"Revenue report shows the previous day for US users","summary":"Calendar days from the API ('2025-03-05') are parsed with new Date(string), which treats them as UTC midnight; in time zones west of UTC the formatted day is one day earlier.","category":"api","difficulty":"intermediate","skills":["javascript-dates","time-zones","testing-with-env"],"requires":["slot:format.date.parse","cap:vitest"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"format.date.parse","value":"export function parseDay(day) {\n  return new Date(day);\n}\n"}]},"fix":{"slots":[{"slot":"format.date.parse","value":"export function parseDay(day) {\n  // A calendar day such as \"2025-03-05\" has no time zone, so build it in local time.\n  const [year, month, date] = day.split('-').map(Number);\n  return new Date(year, month - 1, date);\n}\n"}],"files":[{"path":"tests/format-day-timezone.test.js","from":"fix/tests/format-day-timezone.test.js"}]},"cheats":[{"name":"hard-code-pacific-offset","slots":[{"slot":"format.date.parse","value":"export function parseDay(day) {\n  // The support team is in Pacific time.\n  return new Date(new Date(day).getTime() + 8 * 60 * 60 * 1000);\n}\n"}]},{"name":"revert-the-commit","slots":[{"slot":"format.date.parse","value":"export function parseDay(day) {\n  // A calendar day such as \"2025-03-05\" has no time zone, so build it in local time.\n  const [year, month, date] = day.split('-').map(Number);\n  return new Date(year, month - 1, date);\n}\n"}],"files":[{"path":"src/ext/order-csv/index.js","from":"cheats/empty-extension.js"}]}],"carrier":{"feature":"order-csv","files":[{"path":"src/ext/order-csv/index.js","from":"carrier/src/ext/order-csv/index.js"}]},"commit":{"message":"orders: add a CSV copy action to the Tools menu","persona":"Nayan Jaiswal \u003ctom@opsconsole.mindforge.test\u003e"},"checks":[{"ref":"check.vitest-node","role":"symptom","params":{"env":{"TZ":"America/Los_Angeles"},"paths":["tests/re_api_calendar_day/day.test.jsx"]}},{"ref":"check.vitest-node","role":"symptom","params":{"env":{"TZ":"Pacific/Honolulu"},"paths":["tests/re_api_calendar_day/day.test.jsx"]}}],"symptom":{"vars":{"expected":"A day returned by the API as 2025-03-05 is shown as Mar 5, 2025 wherever the viewer is.","observations":"### Other observations from QA\n\n- Timestamps with a time of day (such as the order's placed-at time) look right.\n- It happens in every browser.\n- The CSV action in the Orders tools was added in the same release.","report":"The finance team in San Francisco compared the Revenue report with the bank statement and every day is shifted by one: the row\nlabelled \"Mar 4\" has the numbers of March 5. The numbers and totals are right, only the day labels are wrong. Colleagues in London see\nthe correct dates, which made it hard to believe at first.","support_tried":"Switched the report range (same shift). Checked the API: it returns 2025-03-05 for that row. It only reproduces on machines set to a US time zone.","title":"Reports list every day one day too early","where":"Reports page (Revenue by day), the Day column. The same helper formats the day labels elsewhere."},"signature":"formatted day is one earlier in time zones west of UTC"},"hints":["Run the date helper tests under another time zone, for example `TZ=America/Los_Angeles npx vitest run`. Compare the Date you get for '2025-03-05' with what you expect.","A date-only ISO string is defined to be UTC midnight when passed to new Date(), but formatting prints it in local time. Which side of the date line does Los Angeles sit?","Build the Date from numeric parts in local time (year, month, day) so the calendar day never crosses a day boundary. Pin the time zone in the test (process.env.TZ) so it fails outside UTC."],"rubric":{"key_points":["Identifies the date-only string parsed as UTC midnight by new Date(string) and then formatted in local time, which moves it to the previous day west of UTC.","Explains the difference between a calendar day (no time zone) and an instant (UTC timestamp).","Fixes it by constructing a local date from the parts (or formatting with timeZone: 'UTC'), not by adding a fixed offset.","Tests with an explicit time zone so the bug cannot hide on a UTC machine."],"misconceptions":["Adding hours to the date fixes it (a fixed offset breaks other time zones and daylight saving).","The API returns the wrong day (the API value is correct; the conversion is wrong).","It only matters for users in the US (any zone west of UTC, and any zone with a day-boundary shift for other inputs)."]},"root_cause":"`parseDay` called `new Date('2025-03-05')`. For a date-only ISO string the JavaScript spec parses the value as UTC midnight, but\n`toLocaleDateString` formats it in the viewer's local time zone. For a viewer in Los Angeles, midnight UTC is still the\nevening of the previous day, so the label was one day early. In UTC and zones east of it the bug is invisible.\n\nA calendar day has no time zone: construct it in local time from its parts, `new Date(year, month - 1, date)`."}}$mfcc294e40$::jsonb, 'lab-bundles/224ca824fe9f260f0ad573b14b1135a9e04befc490ad8c3c06f58546b2abbf64.tar.gz', '224ca824fe9f260f0ad573b14b1135a9e04befc490ad8c3c06f58546b2abbf64', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

-- re.api.http-error-treated-as-success@1.0.0
