VALUES ('332a4cd2-6b74-5879-a628-378277fd7980', NULL, 're.api.http-error-treated-as-success', 'fault', 'react')
ON CONFLICT (org_id, block_key) DO NOTHING;
DO $mf488956e1$ BEGIN
  IF EXISTS (SELECT 1 FROM public.lab_blocks WHERE id = '332a4cd2-6b74-5879-a628-378277fd7980' AND (kind <> 'fault' OR stack <> 'react')) THEN
    RAISE EXCEPTION 'lab block % changed kind or stack; block identity is immutable', 're.api.http-error-treated-as-success';
  END IF;
  IF EXISTS (SELECT 1 FROM public.lab_block_versions WHERE block_id = '332a4cd2-6b74-5879-a628-378277fd7980' AND version = '1.0.0' AND content_hash <> '488956e1e340f502d4a871b00695213d2901fc6f8ffeb2c107483d56babcdcbc') THEN
    RAISE EXCEPTION 'lab block % version % is already published with different content; bump the version', 're.api.http-error-treated-as-success', '1.0.0';
  END IF;
END $mf488956e1$;
INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('4e5bb575-d622-5fb2-8e84-e5ac6a7f0f08', '332a4cd2-6b74-5879-a628-378277fd7980', '1.0.0', '488956e1e340f502d4a871b00695213d2901fc6f8ffeb2c107483d56babcdcbc', $mf488956e1${"kind":"fault","id":"re.api.http-error-treated-as-success","version":"1.0.0","stack":"react","title":"The UI says Saved while the server was down","summary":"The API client only rejects on client errors (4xx), so a 5xx response resolves with its error body and screens show success for a request that failed.","category":"api","difficulty":"intermediate","skills":["fetch","error-handling","http-status"],"requires":["slot:lib.api.check-status","cap:vitest"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"lib.api.check-status","value":"// Server errors are retried by the gateway, so only client errors are treated as failures here.\nif (response.status \u003e= 400 \u0026\u0026 response.status \u003c 500) {\n  throw new ApiError(response.status, `${method} ${path} failed with ${response.status}`);\n}\n"}]},"fix":{"slots":[{"slot":"lib.api.check-status","value":"if (!response.ok) {\n  throw new ApiError(response.status, `${method} ${path} failed with ${response.status}`);\n}\n"}],"files":[{"path":"tests/api-server-errors.test.jsx","from":"fix/tests/api-server-errors.test.jsx"}]},"cheats":[{"name":"only-http-500","slots":[{"slot":"lib.api.check-status","value":"if (response.status === 500) {\n  throw new ApiError(response.status, `${method} ${path} failed with ${response.status}`);\n}\n"}]},{"name":"revert-the-commit","slots":[{"slot":"lib.api.check-status","value":"if (!response.ok) {\n  throw new ApiError(response.status, `${method} ${path} failed with ${response.status}`);\n}\n"}],"files":[{"path":"src/ext/status-breakdown/index.js","from":"cheats/empty-extension.js"}]}],"carrier":{"feature":"status-breakdown","files":[{"path":"src/ext/status-breakdown/index.js","from":"carrier/src/ext/status-breakdown/index.js"}]},"commit":{"message":"orders: add a status breakdown action to the Tools menu","persona":"Nayan Jaiswal \u003crahul@opsconsole.mindforge.test\u003e"},"checks":[{"ref":"check.vitest-node","role":"symptom","params":{"paths":["tests/re_api_http_errors/errors.test.jsx"]}}],"symptom":{"vars":{"expected":"A failed request shows the error message of that screen instead of success or empty data.","observations":"### Other observations from QA\n\n- Client errors such as a validation failure (422) are reported correctly.\n- The network tab shows the failed request with a JSON body `{\"error\": ...}`.\n- The status breakdown action in the Orders tools came in the same release.","report":"During yesterday's brief outage of the customer service the edit form kept showing the green \"Saved\" confirmation, but when\nwe reopened the customers the old email was back. Agents were telling customers their address was updated. Another agent saw\nan Orders page full of \"undefined\" rows at the same time instead of the error banner.","support_tried":"Retried the save after the outage and it worked, so we assumed a one-time glitch. The browser console shows the request answered with 503.","title":"Customer edit says \"Saved\" but the change is lost","where":"Any request that fails with a server error (5xx): saving a customer, loading orders, notes and reports."},"signature":"a 5xx response resolves instead of rejecting"},"hints":["Script a PUT that answers 503 and watch what the save promise does. Does it reject? Compare with a 404 or 422.","fetch resolves for every HTTP status; only network failures reject. The API client is the one place that turns a bad status into an error. Read its status check carefully.","Treat every non-2xx response as an error with response.ok (do not enumerate codes). Add a test that covers several status codes, including 5xx, and one screen that must show its error state."],"rubric":{"key_points":["Identifies that fetch does not reject on HTTP errors and that the client's status check let 5xx responses through as data.","Explains the consequence: error bodies were parsed and treated as successful results (Saved, undefined rows).","Fixes the check at the single client boundary using response.ok (or all non-2xx) rather than patching individual screens or listing codes.","Tests several status codes and the user-visible error state."],"misconceptions":["fetch rejects on 4xx/5xx (it only rejects on network failures).","Checking only for status 500 is enough (502, 503 and 504 are common server errors).","Fixing it in the customer form alone is enough (every screen goes through the same client)."]},"root_cause":"`request()` in the API client turned a response into an error only for client errors (`400 \u003c= status \u003c 500`), based on the\nassumption that the gateway retries server errors. `fetch` itself never rejects for HTTP statuses, so a 5xx response was parsed\nas JSON and returned as if it were a successful result; the customer form showed \"Saved\", and the orders hook received an\nerror body instead of the list.\n\nThe client is the one boundary that must classify responses: `if (!response.ok) throw new ApiError(...)` for every non-2xx status."}}$mf488956e1$::jsonb, 'lab-bundles/25de27367697858c0f1d072d0d23b1edf22ef048826a7a722b3fa3ca5ee5d8c2.tar.gz', '25de27367697858c0f1d072d0d23b1edf22ef048826a7a722b3fa3ca5ee5d8c2', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

-- re.async.optimistic-flag-no-rollback@1.0.0
INSERT INTO public.lab_blocks (id, org_id, block_key, kind, stack)
VALUES ('b02951e4-c5fe-53c1-85d6-f95ced0aa193', NULL, 're.async.optimistic-flag-no-rollback', 'fault', 'react')
ON CONFLICT (org_id, block_key) DO NOTHING;
DO $mfdf473492$ BEGIN
  IF EXISTS (SELECT 1 FROM public.lab_blocks WHERE id = 'b02951e4-c5fe-53c1-85d6-f95ced0aa193' AND (kind <> 'fault' OR stack <> 'react')) THEN
    RAISE EXCEPTION 'lab block % changed kind or stack; block identity is immutable', 're.async.optimistic-flag-no-rollback';
  END IF;
  IF EXISTS (SELECT 1 FROM public.lab_block_versions WHERE block_id = 'b02951e4-c5fe-53c1-85d6-f95ced0aa193' AND version = '1.0.0' AND content_hash <> 'df473492668a4927d01d519aa9e3c308752408c1b65259c92422af47d74b2b6f') THEN
    RAISE EXCEPTION 'lab block % version % is already published with different content; bump the version', 're.async.optimistic-flag-no-rollback', '1.0.0';
  END IF;
END $mfdf473492$;
INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('9c825b72-92ce-50db-9a63-4c173e6e40e6', 'b02951e4-c5fe-53c1-85d6-f95ced0aa193', '1.0.0', 'df473492668a4927d01d519aa9e3c308752408c1b65259c92422af47d74b2b6f', $mfdf473492${"kind":"fault","id":"re.async.optimistic-flag-no-rollback","version":"1.0.0","stack":"react","title":"An order stays flagged after the server refused the flag","summary":"Flagging an order updates the UI at once and then calls the API; when the API fails the error message appears but the optimistic flag state is never rolled back.","category":"races","difficulty":"intermediate","skills":["optimistic-ui","error-handling","react-state"],"requires":["slot:orders.flag.toggle","cap:vitest"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"orders.flag.toggle","value":"setFlagged(next);\ntry {\n  await post(`/api/orders/${order.id}/flag`, { flagged: next });\n} catch (failure) {\n  setError(failure);\n}\n"}]},"fix":{"slots":[{"slot":"orders.flag.toggle","value":"setFlagged(next);\ntry {\n  await post(`/api/orders/${order.id}/flag`, { flagged: next });\n} catch (failure) {\n  setFlagged(!next);\n  setError(failure);\n}\n"}],"files":[{"path":"tests/flag-rollback.test.jsx","from":"fix/tests/flag-rollback.test.jsx"}]},"cheats":[{"name":"wait-for-the-server","slots":[{"slot":"orders.flag.toggle","value":"try {\n  await post(`/api/orders/${order.id}/flag`, { flagged: next });\n  setFlagged(next);\n} catch (failure) {\n  setError(failure);\n}\n"}]},{"name":"revert-the-commit","slots":[{"slot":"orders.flag.toggle","value":"setFlagged(next);\ntry {\n  await post(`/api/orders/${order.id}/flag`, { flagged: next });\n} catch (failure) {\n  setFlagged(!next);\n  setError(failure);\n}\n"}],"files":[{"path":"src/ext/flagged-count/index.js","from":"cheats/empty-extension.js"}]}],"carrier":{"feature":"flagged-count","files":[{"path":"src/ext/flagged-count/index.js","from":"carrier/src/ext/flagged-count/index.js"}]},"commit":{"message":"orders: show how many orders on the page are flagged","persona":"Nayan Jaiswal \u003cdana@opsconsole.mindforge.test\u003e"},"checks":[{"ref":"check.vitest-node","role":"symptom","params":{"paths":["tests/re_async_flag_rollback/flag.test.jsx"]}}],"symptom":{"vars":{"expected":"If the flag cannot be saved, the button goes back to its previous state together with the error message. When the save works the flag shows immediately, without waiting for the server.","observations":"### Other observations from QA\n\n- The error message is shown, so the failure is detected.\n- Unflagging an already flagged order has the same problem in reverse.\n- The flagged-count action in the Orders tools shipped with the same release.","report":"When the API is having a bad day, clicking Flag on an order turns the button to \"Flagged\" and shows the red \"Could not update\nthe flag.\" message at the same time. After reload the order is not flagged, so the team thought it was escalated when it was\nnot. Last week this hid a chargeback dispute for two days.","support_tried":"Retried the click (works when the API is healthy). The mock API rejects the request with a 500 when we simulate a failure.","title":"Order shows as flagged but the flag was not saved","where":"Orders page, the Flag button in the last column of each row."},"signature":"flag state differs from the server after a failed request"},"hints":["Make the flag request fail in a test (a held or scripted POST that answers 500) and look at the button state before and after the answer arrives.","The toggle changes the state first and talks to the server second. What has to happen to the first change when the second step fails?","Restore the previous value in the failure branch next to the error state. Keep the immediate update: the test should still see the button pressed before the server answers."],"rubric":{"key_points":["Identifies that the optimistic update is never undone when the request fails, so UI state and server state diverge.","Explains the optimistic-update contract: apply immediately, confirm on success, roll back on failure.","Fixes the failure branch without removing the optimistic behavior (the button must still flip before the server answers).","Tests both the immediate flip and the rollback with a request that is held and then rejected."],"misconceptions":["Waiting for the server before updating the UI is the fix (it removes the optimistic behavior the page is designed around).","Refetching the whole orders list after an error is enough (it hides the divergence but costs a request and loses other local state)."]},"root_cause":"`useFlagToggle` applies the new flag locally before the request is sent (an optimistic update) and records the error if the\nrequest fails, but the failure branch never restored the previous flag. The component therefore kept showing the flagged\nstate while the server still had the old one.\n\nThe failure branch must undo the optimistic change (`setFlagged(!next)`) in addition to recording the error."}}$mfdf473492$::jsonb, 'lab-bundles/34ed9f81a9944adc0bdea13a5556d923aefaae80a3a2be38e20968e61ef97e67.tar.gz', '34ed9f81a9944adc0bdea13a5556d923aefaae80a3a2be38e20968e61ef97e67', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

-- re.async.typeahead-out-of-order@1.0.0
INSERT INTO public.lab_blocks (id, org_id, block_key, kind, stack)
VALUES ('6af2016d-b5f3-5960-bdd1-1b635be0ce32', NULL, 're.async.typeahead-out-of-order', 'fault', 'react')
ON CONFLICT (org_id, block_key) DO NOTHING;
DO $mfc033a1b3$ BEGIN
  IF EXISTS (SELECT 1 FROM public.lab_blocks WHERE id = '6af2016d-b5f3-5960-bdd1-1b635be0ce32' AND (kind <> 'fault' OR stack <> 'react')) THEN
    RAISE EXCEPTION 'lab block % changed kind or stack; block identity is immutable', 're.async.typeahead-out-of-order';
  END IF;
  IF EXISTS (SELECT 1 FROM public.lab_block_versions WHERE block_id = '6af2016d-b5f3-5960-bdd1-1b635be0ce32' AND version = '1.0.0' AND content_hash <> 'c033a1b366d5e48978e8dc7a98dd0596a6907f6e0ab68ae0a81f3ecd81c959d9') THEN
    RAISE EXCEPTION 'lab block % version % is already published with different content; bump the version', 're.async.typeahead-out-of-order', '1.0.0';
