END $mfc033a1b3$;
INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('20bf5a47-62a4-57cd-8eb4-cb85cbedf041', '6af2016d-b5f3-5960-bdd1-1b635be0ce32', '1.0.0', 'c033a1b366d5e48978e8dc7a98dd0596a6907f6e0ab68ae0a81f3ecd81c959d9', $mfc033a1b3${"kind":"fault","id":"re.async.typeahead-out-of-order","version":"1.0.0","stack":"react","title":"Customer search shows results for an older query","summary":"The customer typeahead sends a request per keystroke and applies every response when it arrives, so a slow answer for an earlier query overwrites the answer for the current one.","category":"races","difficulty":"intermediate","skills":["react-hooks","async-races","abortcontroller"],"requires":["slot:customers.search.effect","cap:vitest"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"customers.search.effect","value":"useEffect(() =\u003e {\n  const term = query.trim();\n  if (term === '') {\n    setState({ results: [], loading: false, error: null });\n    return undefined;\n  }\n  setState((current) =\u003e ({ ...current, loading: true, error: null }));\n  get(`/api/customers?q=${encodeURIComponent(term)}`).then(\n    (results) =\u003e setState({ results, loading: false, error: null }),\n    (error) =\u003e setState((current) =\u003e ({ ...current, loading: false, error })),\n  );\n  return undefined;\n}, [query]);\n"}]},"fix":{"slots":[{"slot":"customers.search.effect","value":"useEffect(() =\u003e {\n  const term = query.trim();\n  if (term === '') {\n    setState({ results: [], loading: false, error: null });\n    return undefined;\n  }\n  const controller = new AbortController();\n  setState((current) =\u003e ({ ...current, loading: true, error: null }));\n  get(`/api/customers?q=${encodeURIComponent(term)}`, { signal: controller.signal }).then(\n    (results) =\u003e setState({ results, loading: false, error: null }),\n    (error) =\u003e {\n      if (error.name !== 'AbortError') setState((current) =\u003e ({ ...current, loading: false, error }));\n    },\n  );\n  return () =\u003e controller.abort();\n}, [query]);\n"}],"files":[{"path":"tests/customer-search-order.test.jsx","from":"fix/tests/customer-search-order.test.jsx"}]},"cheats":[{"name":"wait-for-three-characters","slots":[{"slot":"customers.search.effect","value":"useEffect(() =\u003e {\n  const term = query.trim();\n  if (term.length \u003c 3) {\n    setState({ results: [], loading: false, error: null });\n    return undefined;\n  }\n  setState((current) =\u003e ({ ...current, loading: true, error: null }));\n  get(`/api/customers?q=${encodeURIComponent(term)}`).then(\n    (results) =\u003e setState({ results, loading: false, error: null }),\n    (error) =\u003e setState((current) =\u003e ({ ...current, loading: false, error })),\n  );\n  return undefined;\n}, [query]);\n"}]},{"name":"revert-the-commit","slots":[{"slot":"customers.search.effect","value":"useEffect(() =\u003e {\n  const term = query.trim();\n  if (term === '') {\n    setState({ results: [], loading: false, error: null });\n    return undefined;\n  }\n  const controller = new AbortController();\n  setState((current) =\u003e ({ ...current, loading: true, error: null }));\n  get(`/api/customers?q=${encodeURIComponent(term)}`, { signal: controller.signal }).then(\n    (results) =\u003e setState({ results, loading: false, error: null }),\n    (error) =\u003e {\n      if (error.name !== 'AbortError') setState((current) =\u003e ({ ...current, loading: false, error }));\n    },\n  );\n  return () =\u003e controller.abort();\n}, [query]);\n"}],"files":[{"path":"src/ext/top-customer/index.js","from":"cheats/empty-extension.js"}]}],"carrier":{"feature":"top-customer","files":[{"path":"src/ext/top-customer/index.js","from":"carrier/src/ext/top-customer/index.js"}]},"commit":{"message":"orders: name the top customer in the Tools menu","persona":"Nayan Jaiswal \u003clena@opsconsole.mindforge.test\u003e"},"checks":[{"ref":"check.vitest-node","role":"symptom","params":{"paths":["tests/re_async_typeahead/search.test.jsx"]}}],"symptom":{"vars":{"expected":"The list always matches the text currently in the box, however slowly the server answers.","observations":"### Other observations from QA\n\n- It is never wrong on the office network, only when answers are slow.\n- Looking at the Network tab, the responses sometimes arrive in a different order than the requests were sent.\n- The top-customer action in the Orders tools was added recently.","report":"When I type a customer name quickly the list sometimes ends up showing people for a shorter version of what is in the box.\nI typed \"ali\" and the list showed everyone starting with \"a\" while the box still said \"ali\". Retyping a character fixes it.\nIt happens more often on the slow VPN. Twice I opened the wrong customer because of it.","support_tried":"Slowed my typing down (works), cleared the cache (no change). The API returns correct results when called directly.","title":"Customer search lists people who do not match what I typed","where":"Customers page, the search box above the results list."},"signature":"results of an older query replace the current ones"},"hints":["Use the held requests of @mf/harness (installFetch().hold) to answer two searches in the opposite order from how they were sent. What does the list show at the end?","Every response is applied, whenever it arrives. Something has to decide that an answer no longer belongs to the current query. The effect already returns a cleanup function: what could it do?","Cancel the previous request in the effect cleanup (AbortController) and ignore the abort rejection; keep a test that resolves the requests out of order and checks the visible list."],"rubric":{"key_points":["Identifies the out-of-order response race: responses are applied in arrival order, not in request order.","Explains that the effect cleanup is the right place to cancel or invalidate the previous request.","Fixes it with AbortController (and treats the AbortError as expected) or an equivalent request token, rather than a debounce alone.","Tests it deterministically by controlling the order in which the fake requests resolve."],"misconceptions":["A debounce removes the race (it only makes it rarer; slow answers can still overtake).","Adding a loading flag fixes it (the flag does not say which answer belongs to which query).","Searching only from three characters hides the problem without fixing it."]},"root_cause":"`useCustomerSearch` started a new request on every query change but never invalidated the previous one. The network does\nnot guarantee that responses arrive in the order the requests were sent, so a slow answer for \"a\" could arrive after the\nanswer for \"ali\" and overwrite it with stale results.\n\nThe effect cleanup must cancel the request that belongs to the old query (`AbortController`), and the handler must ignore\nthe resulting `AbortError`, so only the response of the latest query can ever reach the state."}}$mfc033a1b3$::jsonb, 'lab-bundles/383ddfe5db61a615ae1b3f73a19a911d6fc785f72b2a444bc2b3daac83ade9ed.tar.gz', '383ddfe5db61a615ae1b3f73a19a911d6fc785f72b2a444bc2b3daac83ade9ed', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

