VALUES ('bcc03b0f-33fa-5a67-b2a9-e0660bc70325', 'd52d9f4e-7a40-5720-b585-394a42431136', '1.0.0', 'ca4d7de906474fb887f90265b50bbb4ad8d76973d4fbd5622e6f03d6f2df7cb4', $mfca4d7de9${"kind":"app","id":"re.dashboard","version":"1.0.0","stack":"react","title":"Ops Console (React dashboard)","summary":"A support team's internal console on React 19 and Vite - orders with an optimistic flag, customer search and editor, order notes, revenue reports and shared settings - tested with vitest in jsdom.","category":"app","difficulty":"","skills":["react","hooks","vitest","vite"],"provides":["cap:vitest","cap:jsdom","cap:vite-dev"],"budget":{"setup_seconds":3,"workspace_bytes":90000,"grader_bytes":60000},"app":{"language":"js","slots":[{"name":"customers.editor.form","type":"region","description":"The customer form element inside the editor (identity and reset behavior when another customer is selected)."},{"name":"customers.search.effect","type":"region","description":"Search effect of the customer typeahead: empty-query reset, request, cancellation, result handling."},{"name":"format.date.parse","type":"region","description":"parseDay, the conversion of a calendar day string such as 2025-03-05 into a Date."},{"name":"hooks.elapsed.tick","type":"region","description":"The interval callback of useElapsedSeconds (the counter update)."},{"name":"hooks.viewport.subscribe","type":"region","description":"Subscription of useViewportWidth to window resize events, including its cleanup."},{"name":"lib.api.base-url","type":"region","description":"The API base URL, read from the Vite build-time environment."},{"name":"lib.api.check-status","type":"region","description":"The HTTP status check of the API client (what makes a response an error)."},{"name":"notes.panel.rows","type":"region","description":"The note rows rendered by the notes panel (list identity)."},{"name":"orders.flag.toggle","type":"region","description":"The optimistic flag toggle of one order row (state update, request, failu