s/smoke.test.jsx","server/*","index.html"],"features":["orders","customers","notes","reports","settings","order-csv","order-total","flagged-count","status-breakdown","top-customer"],"setup":["bash scripts/bootstrap.sh"],"readiness_path":"/","test_globs":["tests/*","src/*.test.*"]}}$mfca4d7de9$::jsonb, 'lab-bundles/755e22d4115666569d58598f4e710d4826cd5f27daed1fd20cedb0cab7726400.tar.gz', '755e22d4115666569d58598f4e710d4826cd5f27daed1fd20cedb0cab7726400', NULL)
