INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('895b9be7-cf96-50b8-b6d6-88e2c3d80bb1', '8f9fb472-bf3e-5265-ac80-b1879a776086', '1.0.0', '15c6d4e32dccde91e2c58386439dec5c10ba2ea8656c995efb542626edca721b', $mf15c6d4e3${"kind":"fault","id":"re.hooks.missing-effect-dependency","version":"1.0.0","stack":"react","title":"Changing the status filter does not reload the orders","summary":"The orders list reloads when the page changes but not when the status filter changes, because the data effect leaves the status out of its dependency array.","category":"hooks","difficulty":"intermediate","skills":["react-hooks","effect-dependencies","debugging"],"requires":["slot:orders.hook.effect","cap:vitest"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"orders.hook.effect","value":"useEffect(() =\u003e {\n  let ignore = false;\n  setState((current) =\u003e ({ ...current, loading: true, error: null }));\n  get(`/api/orders?status=${status}\u0026page=${page}`).then(\n    (data) =\u003e {\n      if (!ignore) {\n        setState((current) =\u003e ({\n          items: data.items,\n          pages: data.pages,\n          loading: false,\n          error: null,\n          updates: current.updates + 1,\n        }));\n      }\n    },\n    (error) =\u003e {\n      if (!ignore) setState((current) =\u003e ({ ...current, loading: false, error }));\n    },\n  );\n  return () =\u003e {\n    ignore = true;\n  };\n}, [page]);\n"}]},"fix":{"slots":[{"slot":"orders.hook.effect","value":"useEffect(() =\u003e {\n  let ignore = false;\n  setState((current) =\u003e ({ ...current, loading: true, error: null }));\n  get(`/api/orders?status=${status}\u0026page=${page}`).then(\n    (data) =\u003e {\n      if (!ignore) {\n        setState((current) =\u003e ({\n          items: data.items,\n          pages: data.pages,\n          loading: false,\n          error: null,\n          updates: current.updates + 1,\n        }));\n      }\n    },\n    (error) =\u003e {\n      if (!ignore) setState((current) =\u003e ({ ...current, loading: false, error }));\n    },\n  );\n  return () =\u003e {\n    ignore = true;\n  };\n}, [status, page]);\n"}],"files":[{"path":"tests/orders-status-filter.test.jsx","from":"fix/tests/orders-status-filter.test.jsx"}]},"cheats":[{"name":"status-only-dependency","slots":[{"slot":"orders.hook.effect","value":"useEffect(() =\u003e {\n  let ignore = false;\n  setState((current) =\u003e ({ ...current, loading: true, error: null }));\n  get(`/api/orders?status=${status}\u0026page=${page}`).then(\n    (data) =\u003e {\n      if (!ignore) {\n        setState((current) =\u003e ({\n          items: data.items,\n          pages: data.pages,\n          loading: false,\n          error: null,\n          updates: current.updates + 1,\n        }));\n      }\n    },\n    (error) =\u003e {\n      if (!ignore) setState((current) =\u003e ({ ...current, loading: false, error }));\n    },\n  );\n  return () =\u003e {\n    ignore = true;\n  };\n}, [status]);\n"}]},{"name":"revert-the-commit","slots":[{"slot":"orders.hook.effect","value":"useEffect(() =\u003e {\n  let ignore = false;\n  setState((current) =\u003e ({ ...current, loading: true, error: null }));\n  get(`/api/orders?status=${status}\u0026page=${page}`).then(\n    (data) =\u003e {\n      if (!ignore) {\n        setState((current) =\u003e ({\n          items: data.items,\n          pages: data.pages,\n          loading: false,\n          error: null,\n          updates: current.updates + 1,\n        }));\n      }\n    },\n    (error) =\u003e {\n      if (!ignore) setState((current) =\u003e ({ ...current, loading: false, error }));\n    },\n  );\n  return () =\u003e {\n    ignore = true;\n  };\n}, [status, page]);\n"}],"files":[{"path":"src/ext/status-breakdown/index.js","from":"cheats/empty-extension.js"}]}],"carrier":{"feature":"status-breakdown","files":[{"path":"src/ext/status-breakdown/index.js","from":"carrier/src/ext/status-breakdown/index.js"}]},"commit":{"message":"orders: add a status breakdown to the Tools menu","persona":"Nayan Jaiswal \u003crahul@opsconsole.mindforge.test\u003e"},"checks":[{"ref":"check.vitest-node","role":"symptom","params":{"paths":["tests/re_hooks_orders_deps/status-filter.test.jsx"]}}],"symptom":{"vars":{"expected":"Selecting a status reloads the list with only the orders of that status, starting from page 1.","observations":"### Other observations from QA\n\n- After picking a status, going to page 2 and back shows the filtered rows.\n- Nothing is logged in the browser console.\n- The status breakdown action in the Tools menu was added in the same release.","report":"On the Orders page the status dropdown (all / pending / paid / shipped) changes its label but the table keeps showing the\nsame rows. Choosing \"paid\" still lists pending orders. The pagination buttons work, and so does the filter after I click Next\nand then Previous, so I assumed the filter was flaky. Three agents have now sent a pending order out as if it were paid.","support_tried":"Cleared local storage, tried two browsers, restarted the mock API. The API itself returns the right rows when called with `?status=paid`.","title":"Status filter on Orders does nothing","where":"Orders page, the Status dropdown in the toolbar."},"signature":"status change does not trigger a request"},"hints":["Open the Network tab (or count the calls in a test) while you change the status filter. Is a request sent at all? Then compare with what happens when you change the page.","An effect re-runs only when something in its dependency array changed. Compare the values the effect reads with the values it lists.","Add the missing value to the dependency array. A test with a scripted fetch that returns different rows per status will fail before the fix and pass after it, and also check that one change causes exactly one request."],"rubric":{"key_points":["Identifies a missing effect dependency: the effect reads status but only lists the page, so a status change never re-runs it.","Explains why the page change worked (it is in the dependency array) and why the filter appeared to work after paging back and forth.","Fixes the dependency array rather than removing it or forcing reloads, and keeps the request count at one per change.","Mentions the exhaustive-deps lint rule or a test that changes only the filter as prevention."],"misconceptions":["Removing the dependency array fixes it (the effect then runs after every render and, because it sets state, loops).","The API ignores the status parameter (the API is fine; the request is never sent)."]},"root_cause":"The data effect in `useOrders` reads both `status` and `page` but its dependency array was `[page]`. React only re-runs an\neffect when a listed dependency changes, so selecting another status updated the dropdown state but never requested the\nnew rows. Changing the page re-ran the effect, which then used the current status, which is why the filter seemed to work\nafter paging.\n\nThe dependency array must list every reactive value the effect reads: `[status, page]`."}}$mf15c6d4e3$::jsonb, 'lab-bundles/34a0ead53d1efa2ae1e438d4e0d77980320dbf97fadb68907b1ff247cc6e9af0.tar.gz', '34a0ead53d1efa2ae1e438d4e0d77980320dbf97fadb68907b1ff247cc6e9af0', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

-- re.hooks.object-dependency-loop@1.0.0
INSERT INTO public.lab_blocks (id, org_id, block_key, kind, stack)
VALUES ('fadffcca-081f-5300-86f4-a4149e79feaf', NULL, 're.hooks.object-dependency-loop', 'fault', 'react')
