INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('04951822-47aa-544a-9e9d-4220e689055a', 'fadffcca-081f-5300-86f4-a4149e79feaf', '1.0.0', '942c1c166ee7778a0e641594b91bba13d7e2518d98b3582e093fe9efbc2a28bd', $mf942c1c16${"kind":"fault","id":"re.hooks.object-dependency-loop","version":"1.0.0","stack":"react","title":"The Reports page hammers the API","summary":"The revenue hook lists an options object in its effect dependencies; the page builds a new object on every render, so every response triggers another request in an endless loop.","category":"hooks","difficulty":"intermediate","skills":["react-hooks","referential-identity","network-debugging"],"requires":["slot:reports.hook.effect","cap:vitest"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"reports.hook.effect","value":"useEffect(() =\u003e {\n  let ignore = false;\n  get(`/api/reports/revenue?days=${options.days}`).then(\n    (data) =\u003e {\n      if (!ignore) setState({ days: data.days, error: null, settled: true });\n    },\n    (error) =\u003e {\n      if (!ignore) setState((current) =\u003e ({ ...current, error, settled: true }));\n    },\n  );\n  return () =\u003e {\n    ignore = true;\n  };\n}, [options]);\n"}]},"fix":{"slots":[{"slot":"reports.hook.effect","value":"const { days: range } = options;\nuseEffect(() =\u003e {\n  let ignore = false;\n  get(`/api/reports/revenue?days=${range}`).then(\n    (data) =\u003e {\n      if (!ignore) setState({ days: data.days, error: null, settled: true });\n    },\n    (error) =\u003e {\n      if (!ignore) setState((current) =\u003e ({ ...current, error, settled: true }));\n    },\n  );\n  return () =\u003e {\n    ignore = true;\n  };\n}, [range]);\n"}],"files":[{"path":"tests/revenue-requests.test.jsx","from":"fix/tests/revenue-requests.test.jsx"}]},"cheats":[{"name":"fetch-once-only","slots":[{"slot":"reports.hook.effect","value":"useEffect(() =\u003e {\n  let ignore = false;\n  get(`/api/reports/revenue?days=${options.days}`).then(\n    (data) =\u003e {\n      if (!ignore) setState({ days: data.days, error: null, settled: true });\n    },\n    (error) =\u003e {\n      if (!ignore) setState((current) =\u003e ({ ...current, error, settled: true }));\n    },\n  );\n  return () =\u003e {\n    ignore = true;\n  };\n}, []);\n"}]},{"name":"revert-the-commit","slots":[{"slot":"reports.hook.effect","value":"const { days: range } = options;\nuseEffect(() =\u003e {\n  let ignore = false;\n  get(`/api/reports/revenue?days=${range}`).then(\n    (data) =\u003e {\n      if (!ignore) setState({ days: data.days, error: null, settled: true });\n    },\n    (error) =\u003e {\n      if (!ignore) setState((current) =\u003e ({ ...current, error, settled: true }));\n    },\n  );\n  return () =\u003e {\n    ignore = true;\n  };\n}, [range]);\n"}],"files":[{"path":"src/ext/order-csv/index.js","from":"cheats/empty-extension.js"}]}],"carrier":{"feature":"order-csv","files":[{"path":"src/ext/order-csv/index.js","from":"carrier/src/ext/order-csv/index.js"}]},"commit":{"message":"orders: copy the visible orders as CSV from the Tools menu","persona":"Nayan Jaiswal \u003ctom@opsconsole.mindforge.test\u003e"},"checks":[{"ref":"check.vitest-node","role":"symptom","params":{"paths":["tests/re_hooks_report_loop/revenue.test.jsx"]}}],"symptom":{"vars":{"expected":"One request when the page opens and one more each time the range changes.","observations":"### Other observations from QA\n\n- The browser Network tab shows the same `/api/reports/revenue?days=30` request over and over.\n- Everything else in the console works normally.\n- The CSV action on the Orders page went out in the same release.","report":"Opening the Reports tab makes the browser fan spin up and the tab becomes sluggish after a few seconds. Our API dashboard\nshows hundreds of requests per minute to the revenue endpoint from a single browser. The numbers on the page are right, it just\nnever stops asking. Ops rate-limited the support network because of it.","support_tried":"Closed other tabs, switched networks, restarted the API. The request storm starts the moment the Reports tab is opened and stops when you leave it.","title":"Reports tab freezes and the API is being hammered","where":"The Reports page (Revenue), any range."},"signature":"repeated identical requests to /api/reports/revenue"},"hints":["Count the requests the Reports page makes after it has finished loading, for example with the scripted fetch from @mf/harness. It should be one. What is it?","Each response calls setState, which re-renders the page, and the page creates a fresh options object while rendering. Look at how the effect decides whether to run again.","Depend on the primitive the effect actually uses (the number of days), not on the object it arrived in. Then assert the request count in a test, after letting the page settle."],"rubric":{"key_points":["Identifies the loop: the options object is a new reference on every render, the effect lists the object, so every state update re-runs the effect, which fetches, which updates state.","Explains referential identity versus value equality for effect dependencies.","Fixes it by depending on the primitive value (or memoizing the object at the call site), not by dropping the dependencies.","Verifies the fix by asserting the number of requests, including a range change that must produce exactly one more."],"misconceptions":["An empty dependency array is the fix (the range selector then stops working).","Debouncing the fetch fixes it (it only slows the loop down).","The API response is different each time (the loop is caused by the render cycle, not the data)."]},"root_cause":"`useRevenue(options)` took an options object and its data effect listed `[options]` as its dependency. `ReportsPage`\ncreates `{ days: range }` while rendering, so every render produced a new object; React compares dependencies with\n`Object.is`, saw a change and re-ran the effect. Each response then called `setState`, which re-rendered the page, which\ncreated another object: an endless fetch loop.\n\nThe effect only needs the number of days, so it must depend on that primitive: read `options.days` into a variable and use\n`[range]`."}}$mf942c1c16$::jsonb, 'lab-bundles/1b262a9176ac26191bb35df0dd1aa54991084f5973404cdf93d0b052707b986f.tar.gz', '1b262a9176ac26191bb35df0dd1aa54991084f5973404cdf93d0b052707b986f', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

