  IF EXISTS (SELECT 1 FROM public.lab_block_versions WHERE block_id = 'f732fdb1-d8be-5677-bee0-ea031eb8a17b' AND version = '1.0.0' AND content_hash <> 'dc79a510bd55de8bb19bc6442f27c849a61761bb8b89846d542d70162be8aa5a') THEN
