INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('39983e5c-8662-5c0b-9ae8-0665476a54b6', 'f732fdb1-d8be-5677-bee0-ea031eb8a17b', '1.0.0', 'dc79a510bd55de8bb19bc6442f27c849a61761bb8b89846d542d70162be8aa5a', $mfdc79a510${"kind":"fault","id":"re.hooks.stale-interval-closure","version":"1.0.0","stack":"react","title":"The 'updated N seconds ago' badge never gets past 1","summary":"The refresh badge on the orders page counts seconds with a timer, but the counter freezes after the first tick because the interval callback keeps reading the value from the render that created it.","category":"hooks","difficulty":"beginner","skills":["react-hooks","closures","debugging"],"requires":["slot:hooks.elapsed.tick","cap:vitest"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"hooks.elapsed.tick","value":"setSeconds(seconds + 1);\n"}]},"fix":{"slots":[{"slot":"hooks.elapsed.tick","value":"setSeconds((current) =\u003e current + 1);\n"}],"files":[{"path":"tests/elapsed-seconds.test.jsx","from":"fix/tests/elapsed-seconds.test.jsx"}]},"cheats":[{"name":"cap-the-counter","slots":[{"slot":"hooks.elapsed.tick","value":"setSeconds((current) =\u003e Math.min(current + 1, 30));\n"}]},{"name":"revert-the-commit","slots":[{"slot":"hooks.elapsed.tick","value":"setSeconds((current) =\u003e current + 1);\n"}],"files":[{"path":"src/ext/order-total/index.js","from":"cheats/empty-extension.js"}]}],"carrier":{"feature":"order-total","files":[{"path":"src/ext/order-total/index.js","from":"carrier/src/ext/order-total/index.js"}]},"commit":{"message":"orders: show the page total in the Tools menu","persona":"Nayan Jaiswal \u003cdana@opsconsole.mindforge.test\u003e"},"checks":[{"ref":"check.vitest-node","role":"symptom","params":{"paths":["tests/re_hooks_stale_timer/elapsed.test.jsx"]}}],"symptom":{"vars":{"expected":"The badge counts up every second (2s, 3s, ...) until the list is loaded again.","observations":"### Other observations from QA\n\n- The first second looks right, then it sticks.\n- It happens in the dev build as well, so it is not a production build problem.\n- The Tools menu on the same page got a new action around the same time.","report":"The small badge next to the status filter on the Orders page is supposed to tell us how fresh the list is (\"Updated 12s ago\").\nSince last week it shows \"Updated 1s ago\" and then never changes, however long the page stays open. Two people on the floor\nrefreshed the browser thinking the data was stuck, and one of them double-processed an order because the list looked stale.","support_tried":"Hard-reloaded the page and tried another browser: same result. The orders themselves load fine.","title":"Orders page says \"Updated 1s ago\" forever","where":"The Orders page, the badge right of the status filter. It restarts at 0 whenever new orders load."},"signature":"the elapsed-seconds counter stops at 1"},"hints":["Write a small test that renders the hook with fake timers, advances the clock by several seconds and reads the value. Does the number follow the clock, and where does it stop?","The interval is created once per effect run, so its callback only ever sees the values from the render in which the effect ran. Look at which variable the callback reads when it computes the next number.","Update the state from its previous value (a functional update) so the callback no longer depends on a captured render value, then keep a test with fake timers that advances well past one second."],"rubric":{"key_points":["Identifies a stale closure: the interval callback reads the counter from the render that created the interval, so every tick computes the same next value.","Explains why the effect does not re-run (its dependency array only holds the reset key) and that the interval is meant to live across renders.","Fixes it with a functional state update (or a ref) instead of widening the dependency array and restarting the timer on every tick.","Proves the fix with a fake-timer test that advances beyond one second and asserts the counter value."],"misconceptions":["Adding the counter to the effect dependency array is a good fix (it tears down and recreates the interval on every tick, so the timer drifts and tests that count timers fail).","The state update is asynchronous and 'does not apply in time' (the update does apply; the value computed from it is stale)."]},"root_cause":"`useElapsedSeconds` creates one interval per effect run and the interval callback computed the next value as `seconds + 1`.\nThe callback closes over the `seconds` of the render in which the effect ran, which is always `0` (the effect only re-runs\nwhen the reset key changes). Every tick therefore sets the state to `1`.\n\nThe fix is a functional update, `setSeconds((current) =\u003e current + 1)`, which reads the latest state at the time the update is\napplied and keeps the interval alive across renders."}}$mfdc79a510$::jsonb, 'lab-bundles/9c488b752f2b763e95a1b299fe1fe4e9635ed3ae511e373cfe63ef65c746fa22.tar.gz', '9c488b752f2b763e95a1b299fe1fe4e9635ed3ae511e373cfe63ef65c746fa22', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

