INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('cdbfaa65-5bae-54ce-9cc6-1e67f2a0fb7d', '3289ca8a-0e53-5e91-951c-95337e70f59c', '1.0.0', 'ce8d5ab785c8398ec1e83caeddd5ab20f5f7dd7688c8e5d51d7926f0680e452b', $mfce8d5ab7${"kind":"fault","id":"re.perf.context-value-rerenders","version":"1.0.0","stack":"react","title":"Typing in the quick filter makes every page re-render","summary":"The settings provider builds a new context value object on every render, so every component reading the settings re-renders whenever the provider's parent does.","category":"perf","difficulty":"intermediate","skills":["react-profiler","context","memoization"],"requires":["slot:settings.provider.value","cap:vitest"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"settings.provider.value","value":"const value = { ...settings, update };\n"}]},"fix":{"slots":[{"slot":"settings.provider.value","value":"const value = useMemo(() =\u003e ({ ...settings, update }), [settings, update]);\n"}],"files":[{"path":"tests/settings-context-renders.test.jsx","from":"fix/tests/settings-context-renders.test.jsx"}]},"cheats":[{"name":"memoize-without-settings","slots":[{"slot":"settings.provider.value","value":"const value = useMemo(() =\u003e ({ ...settings, update }), [update]);\n"}]},{"name":"revert-the-commit","slots":[{"slot":"settings.provider.value","value":"const value = useMemo(() =\u003e ({ ...settings, update }), [settings, update]);\n"}],"files":[{"path":"src/ext/order-total/index.js","from":"cheats/empty-extension.js"}]}],"carrier":{"feature":"order-total","files":[{"path":"src/ext/order-total/index.js","from":"carrier/src/ext/order-total/index.js"}]},"commit":{"message":"orders: add a page total to the Tools menu","persona":"Nayan Jaiswal \u003ctom@opsconsole.mindforge.test\u003e"},"checks":[{"ref":"check.vitest-node","role":"symptom","params":{"paths":["tests/re_perf_context_value/context.test.jsx"]}}],"symptom":{"vars":{"expected":"Typing in the filter only re-renders what depends on the filter text, not every component that reads the settings.","observations":"### Other observations from QA\n\n- Row components read the currency from the shared settings.\n- In the profiler the reason for the render is \"Context changed\" although no setting was changed.\n- The page total action in the Orders tools shipped with the same release.","report":"Typing in the Quick filter box in the header has become noticeably laggy on the orders table with a few hundred rows,\nand the React profiler shows every row re-rendering for each keystroke even though only the filter text changed.\nStaff on older laptops say the characters appear a second late.","support_tried":"Switched to compact density and a smaller page size (slightly better). Changing the currency or density still works as it should.","title":"Console feels laggy while typing in the quick filter","where":"The Quick filter in the header while the Orders or Reports page is open."},"signature":"settings consumers re-render without a settings change"},"hints":["Count renders with the render probe from @mf/harness: put a consumer of the settings under the provider, re-render the provider's parent without changing any setting, and compare the render counts.","Context consumers re-render when the provided value changes by reference. What does the provider create each time it renders?","Memoize the value with the right dependencies (the settings and the stable update function), and test both directions: no re-render without a change, and a re-render when a setting does change."],"rubric":{"key_points":["Identifies the new object created on every provider render, which changes the context value reference and forces every consumer to re-render.","Explains that context compares by reference and that the parent re-render (quick filter state) triggers the provider render.","Fixes it with useMemo and a correct dependency list (settings and update), not an empty list.","Verifies by counting renders of a consumer in both situations (unrelated parent update and a real setting change)."],"misconceptions":["Wrapping every row in React.memo fixes it (rows read the context, so they still re-render when the value changes).","An empty dependency array in useMemo is fine (settings changes then never reach the consumers).","Moving the quick filter state into a ref would be the right fix (it removes the filter's rendering instead of the cause)."]},"root_cause":"`SettingsProvider` created `{ ...settings, update }` on every render. The quick filter lives in `App`, so typing re-renders\nthe provider's parent and the provider itself; each render produced a new object, React compared it by reference with\nthe previous value, saw a change and re-rendered every consumer of the context (every table row).\n\nThe value must keep its identity while the settings are unchanged: `useMemo(() =\u003e ({ ...settings, update }), [settings,\nupdate])`."}}$mfce8d5ab7$::jsonb, 'lab-bundles/9b8ab1675d4a363ca6a8d717f7b75af2d44c8873999a531424339246fba6b6cf.tar.gz', '9b8ab1675d4a363ca6a8d717f7b75af2d44c8873999a531424339246fba6b6cf', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

-- re.perf.resize-listener-leak@1.0.0
INSERT INTO public.lab_blocks (id, org_id, block_key, kind, stack)
VALUES ('2d513877-808d-50a2-a89c-6d7376e0cfff', NULL, 're.perf.resize-listener-leak', 'fault', 'react')
