  END IF;
  IF EXISTS (SELECT 1 FROM public.lab_block_versions WHERE block_id = '2d513877-808d-50a2-a89c-6d7376e0cfff' AND version = '1.0.0' AND content_hash <> '1a6275612e0cedc407e6a1fbd2085216219189fb0e56e915d6e3fdad4ab1a5fe') THEN
    RAISE EXCEPTION 'lab block % version % is already published with different content; bump the version', 're.perf.resize-listener-leak', '1.0.0';
  END IF;
END $mf1a627561$;
INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('578643f9-80b1-5027-99ec-32778f703a33', '2d513877-808d-50a2-a89c-6d7376e0cfff', '1.0.0', '1a6275612e0cedc407e6a1fbd2085216219189fb0e56e915d6e3fdad4ab1a5fe', $mf1a627561${"kind":"fault","id":"re.perf.resize-listener-leak","version":"1.0.0","stack":"react","title":"Memory and CPU grow every time the Orders page is opened","summary":"The viewport hook adds a window resize listener but never removes it, so every visit to the Orders page leaves another live listener (and a component instance) behind.","category":"perf","difficulty":"intermediate","skills":["react-effects","cleanup","memory-leaks"],"requires":["slot:hooks.viewport.subscribe","cap:vitest"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"hooks.viewport.subscribe","value":"const onResize = () =\u003e setWidth(window.innerWidth);\nwindow.addEventListener('resize', onResize);\n"}]},"fix":{"slots":[{"slot":"hooks.viewport.subscribe","value":"const onResize = () =\u003e setWidth(window.innerWidth);\nwindow.addEventListener('resize', onResize);\nreturn () =\u003e window.removeEventListener('resize', onResize);\n"}],"files":[{"path":"tests/viewport-listener.test.jsx","from":"fix/tests/viewport-listener.test.jsx"}]},"cheats":[{"name":"remove-a-different-function","slots":[{"slot":"hooks.viewport.subscribe","value":"const onResize = () =\u003e setWidth(window.innerWidth);\nwindow.addEventListener('resize', onResize);\nreturn () =\u003e window.removeEventListener('resize', () =\u003e setWidth(window.innerWidth));\n"}]},{"name":"revert-the-commit","slots":[{"slot":"hooks.viewport.subscribe","value":"const onResize = () =\u003e setWidth(window.innerWidth);\nwindow.addEventListener('resize', onResize);\nreturn () =\u003e window.removeEventListener('resize', onResize);\n"}],"files":[{"path":"src/ext/flagged-count/index.js","from":"cheats/empty-extension.js"}]}],"carrier":{"feature":"flagged-count","files":[{"path":"src/ext/flagged-count/index.js","from":"carrier/src/ext/flagged-count/index.js"}]},"commit":{"message":"orders: add a flagged-orders count to the Tools menu","persona":"Nayan Jaiswal \u003cdana@opsconsole.mindforge.test\u003e"},"checks":[{"ref":"check.vitest-node","role":"symptom","params":{"paths":["tests/re_perf_listener_leak/viewport.test.jsx"]}}],"symptom":{"vars":{"expected":"Leaving a page releases everything it registered; memory and the work done per resize stay flat.","observations":"### Other observations from QA\n\n- In the browser's performance monitor the \"JS event listeners\" counter goes up by one on every visit to Orders.\n- The compact layout switch (narrow window) still works.\n- The flagged-count action in the Orders tools shipped in the same release.","report":"By the end of a shift the console is noticeably slower, and resizing the browser window makes the fan spin. A reload brings\nit back to normal for an hour or two. Browser memory for the tab grows by a few MB every time the team switches between Orders\nand the other pages. Our floor staff open the Orders page hundreds of times per day.","support_tried":"Reloading helps for a while. Closing other tabs made no difference. The numbers on screen stay correct throughout.","title":"Console slows down over a shift and resizing gets sluggish","where":"The whole console after repeatedly switching between pages. Resizing the window is the easiest way to feel it."},"signature":"listener count increases with every mount of the orders table"},"hints":["Count live listeners: trackListeners() from @mf/harness patches addEventListener and removeEventListener. Mount and unmount the hook a few times and look at the count.","Anything an effect registers outside React (a window listener, a timer, a subscription) has to be undone by the effect's cleanup function. Does this effect return one?","Return a cleanup that calls removeEventListener with exactly the same function, event type and options that were added. A new arrow function with the same body is a different listener."],"rubric":{"key_points":["Identifies the missing effect cleanup: the resize listener on window is never removed when the component unmounts.","Explains that removal needs the same function reference (and capture flag) as the registration.","Describes the effect on memory (the listener keeps the unmounted component's state setter and closure alive) and on CPU (every resize runs every leaked handler).","Verifies with a listener counter across mount and unmount cycles rather than by eye."],"misconceptions":["React removes window listeners for you when a component unmounts (it only removes its own event handlers).","Passing { once: true } fixes it (it removes the listener after the first event, not on unmount).","Removing with a new arrow function is equivalent (removeEventListener matches by function identity)."]},"root_cause":"`useViewportWidth` called `window.addEventListener('resize', onResize)` inside an effect and returned nothing. The effect has\nno cleanup, so when the orders table unmounted the listener stayed registered on `window`, still holding a reference to the\nunmounted component's state setter. Every later visit added another listener, and every resize event ran all of them.\n\nThe effect must return a cleanup that calls `window.removeEventListener('resize', onResize)` with the same function it\nregistered."}}$mf1a627561$::jsonb, 'lab-bundles/a05a50e17ae6a51c51de0cb3dbf219ca0379916b2c2a8d982aa51ea8a5899cd7.tar.gz', 'a05a50e17ae6a51c51de0cb3dbf219ca0379916b2c2a8d982aa51ea8a5899cd7', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

-- re.state.form-keeps-previous-customer@1.0.0
