INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('5f026929-8781-5eca-95c8-3cf4cd25b107', '3ec0f300-aca2-5d2a-99ea-59d908f7de94', '1.0.0', 'efdc462c047681f65c781c7ecb7fb168633badc8050f1165dbc6ad3bcb6a65a5', $mfefdc462c${"kind":"fault","id":"re.state.form-keeps-previous-customer","version":"1.0.0","stack":"react","title":"The customer editor shows the previous customer's details","summary":"The editor form copies the customer prop into its own state once; when another customer is selected the form keeps the old values because nothing resets its state.","category":"state","difficulty":"intermediate","skills":["react-state","derived-state","component-identity"],"requires":["slot:customers.editor.form","cap:vitest"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"customers.editor.form","value":"\u003cCustomerForm customer={customer} /\u003e\n"}]},"fix":{"slots":[{"slot":"customers.editor.form","value":"\u003cCustomerForm key={customer.id} customer={customer} /\u003e\n"}],"files":[{"path":"tests/customer-editor-reset.test.jsx","from":"fix/tests/customer-editor-reset.test.jsx"}]},"cheats":[{"name":"key-by-name","slots":[{"slot":"customers.editor.form","value":"\u003cCustomerForm key={customer.name} customer={customer} /\u003e\n"}]},{"name":"revert-the-commit","slots":[{"slot":"customers.editor.form","value":"\u003cCustomerForm key={customer.id} customer={customer} /\u003e\n"}],"files":[{"path":"src/ext/top-customer/index.js","from":"cheats/empty-extension.js"}]}],"carrier":{"feature":"top-customer","files":[{"path":"src/ext/top-customer/index.js","from":"carrier/src/ext/top-customer/index.js"}]},"commit":{"message":"orders: add a top-customer action to the Tools menu","persona":"Nayan Jaiswal \u003crahul@opsconsole.mindforge.test\u003e"},"checks":[{"ref":"check.vitest-node","role":"symptom","params":{"paths":["tests/re_state_form_reset/editor.test.jsx"]}}],"symptom":{"vars":{"expected":"The form always shows the customer that was just selected.","observations":"### Other observations from QA\n\n- The first customer you pick in a session always looks right.\n- The search results are correct each time.\n- The top-customer tool in Orders was added in the same release.","report":"After I look at one customer and then pick another from the search results, the edit form still shows the first\ncustomer's name and email. The heading and the data on the server are right, only the fields are stale. I saved once without\nnoticing and overwrote Bob's email with Alice's. We found three customers with swapped emails this week.","support_tried":"Reloading the page between customers works, and so does clicking a customer twice sometimes. The API returns the right customer each time.","title":"Editing a customer saves details of the wrong person","where":"Customers page: search, pick a customer, then pick a different one without reloading."},"signature":"form fields do not follow the selected customer"},"hints":["Select two different customers one after the other in a test and read the form fields after the second one has loaded. Which values do you see?","The form copies its prop into useState when it is first rendered and never looks at the prop again. What would make React throw that state away when the selection changes?","Give the form a key that is the identity of the customer so it remounts for a different customer. Check the case of two customers with the same name."],"rubric":{"key_points":["Identifies props copied into state: `useState(customer.name)` only reads the prop on mount, so a new customer prop does not update the fields.","Explains the reset-with-key pattern (remount for a different entity) versus syncing state from props in an effect.","Chooses the customer id as the key, not a mutable or non-unique field such as the name.","Tests selecting two customers sequentially, including two with the same name."],"misconceptions":["A useEffect that copies the prop into state is the recommended fix (it renders one frame with the old values and breaks edits in progress).","Keying by the customer name is enough (two customers can share a name).","The data is stale from the server (the data is right; the stale part is local component state)."]},"root_cause":"`CustomerForm` stores the name and email in `useState(customer.name)` and `useState(customer.email)`. Initial state is only\nread when the component mounts. `CustomerEditor` rendered the same `CustomerForm` element for every customer, so selecting\nanother customer updated the `customer` prop while React kept the existing component instance and its old state.\n\nGiving the form a key equal to the customer id makes React unmount the old form and mount a new one with fresh state for\nevery different customer."}}$mfefdc462c$::jsonb, 'lab-bundles/6edde29a7724c13540062f1f0f5ac93b92e3f85ca046732084e13b6837e59da0.tar.gz', '6edde29a7724c13540062f1f0f5ac93b92e3f85ca046732084e13b6837e59da0', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

