  END IF;
  IF EXISTS (SELECT 1 FROM public.lab_block_versions WHERE block_id = '6ec241a0-d5f9-5ed0-9b0e-38024d98d986' AND version = '1.0.0' AND content_hash <> '694bcfa24092a41ccb3459cad2b70f9e440c40e423c2c1a517bc524f912be564') THEN
