INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('151dae61-5dac-51f9-86a6-52220614f452', '6ec241a0-d5f9-5ed0-9b0e-38024d98d986', '1.0.0', '694bcfa24092a41ccb3459cad2b70f9e440c40e423c2c1a517bc524f912be564', $mf694bcfa2${"kind":"fault","id":"re.state.index-as-key","version":"1.0.0","stack":"react","title":"Deleting a note makes the next note show the wrong text","summary":"The notes list keys its rows by array index, so after a delete React hands the row state (the text being edited) of the removed note to the note that moved into its place.","category":"state","difficulty":"beginner","skills":["react-reconciliation","keys","debugging"],"requires":["slot:notes.panel.rows","cap:vitest"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"notes.panel.rows","value":"const rows = notes.map((note, index) =\u003e \u003cNoteRow key={index} note={note} onSave={save} onDelete={remove} /\u003e);\n"}]},"fix":{"slots":[{"slot":"notes.panel.rows","value":"const rows = notes.map((note) =\u003e \u003cNoteRow key={note.id} note={note} onSave={save} onDelete={remove} /\u003e);\n"}],"files":[{"path":"tests/notes-keys.test.jsx","from":"fix/tests/notes-keys.test.jsx"}]},"cheats":[{"name":"key-by-text","slots":[{"slot":"notes.panel.rows","value":"const rows = notes.map((note) =\u003e \u003cNoteRow key={note.text} note={note} onSave={save} onDelete={remove} /\u003e);\n"}]},{"name":"revert-the-commit","slots":[{"slot":"notes.panel.rows","value":"const rows = notes.map((note) =\u003e \u003cNoteRow key={note.id} note={note} onSave={save} onDelete={remove} /\u003e);\n"}],"files":[{"path":"src/ext/order-csv/index.js","from":"cheats/empty-extension.js"}]}],"carrier":{"feature":"order-csv","files":[{"path":"src/ext/order-csv/index.js","from":"carrier/src/ext/order-csv/index.js"}]},"commit":{"message":"orders: let the Tools menu copy the visible orders as CSV","persona":"Nayan Jaiswal \u003clena@opsconsole.mindforge.test\u003e"},"checks":[{"ref":"check.vitest-node","role":"symptom","params":{"paths":["tests/re_state_index_key/notes.test.jsx"]}}],"symptom":{"vars":{"expected":"Deleting a note removes only that note: every remaining row keeps showing its own note, including text that was edited but not saved yet.","observations":"### Other observations from QA\n\n- It does not happen when I delete the last note in the list.\n- Two of the notes on my order have exactly the same text (\"Follow up\").\n- The CSV action in the Orders tools came in the same release.","report":"On the order notes page I deleted the first note of an order and the note below it now shows the text of the note I just\ndeleted, with the second note's real text gone from the screen. Unsaved edits end up in the wrong row as well. After a\nreload everything is correct again, but if I press Save on a row at that point the wrong text gets stored on the wrong\nnote. Our team lead lost a customer callback number this way.","support_tried":"Reloading the page always shows the saved data correctly, so the server data is fine. Only happens with unsaved edits and a delete.","title":"Deleting a note leaves another note showing the deleted text","where":"Order notes page, the list of notes of an order (inline text fields with Save and Delete)."},"signature":"row state follows the position, not the note"},"hints":["Reproduce it in a test: three notes, type a draft into the second one without saving, delete the first one, and read the values of the text fields that remain.","Each row keeps its draft in its own state. React decides which old row a new row corresponds to by its key. What is used as the key in the notes list?","Use a stable unique identity of the note (its id) as the key. A key derived from the text breaks as soon as two notes share the same text."],"rubric":{"key_points":["Identifies array index used as the key: after a delete the rows shift positions, so React hands the old row's state (the draft) to the wrong note.","Explains that keys define component identity across renders and must be stable and unique among siblings.","Fixes it with the note id (not text or a generated value on every render).","Tests with an unsaved draft and a delete of an earlier row, ideally with duplicate texts."],"misconceptions":["Using the note text as the key is fine (duplicates collide and edits change the text-based identity).","Generating a random key per render fixes it (every render remounts every row and loses focus and state).","Saving before deleting avoids the bug (it hides the symptom for one workflow)."]},"root_cause":"`NotesPanel` rendered `\u003cNoteRow key={index} /\u003e`. Each `NoteRow` keeps the user's unsaved text in local state and React ties\nthat state to the key. After deleting the first note the remaining notes move up one position, so the row with key `0` now\nrenders the second note but keeps the draft of the first, and so on down the list.\n\nKeys must identify the item, not its position: `key={note.id}`."}}$mf694bcfa2$::jsonb, 'lab-bundles/c3486f473fbf2ec6a0e00222e8e71af5fac478405cbf52b736312d0b79da72e6.tar.gz', 'c3486f473fbf2ec6a0e00222e8e71af5fac478405cbf52b736312d0b79da72e6', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

