INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('e6243759-ebfe-50f7-aa37-32ba947bad2a', '564fc540-dcf9-5ccc-9190-ebb4dddb84ad', '1.0.0', '7a385943dafa3411e23a4e3d36c68b0ec33494d0c83c9ce929db768714dcfc23', $mf7a385943${"kind":"data","id":"seed.dirty","version":"1.0.0","stack":"django","title":"Dirty production-like dataset","summary":"The small dataset plus NULLs, duplicate names, legacy enum values, duplicate active subscriptions (when the schema allows them) and paid orders without invoices.","category":"data","difficulty":"","skills":["data","migrations"],"params":{"properties":{"customers":{"default":60,"maximum":500,"minimum":20,"type":"integer"},"dirty_percent":{"default":20,"description":"How much of each dirtied column is affected.","maximum":45,"minimum":5,"type":"integer"},"orders":{"default":400,"maximum":5000,"minimum":50,"type":"integer"},"products":{"default":120,"maximum":1000,"minimum":20,"type":"integer"}},"type":"object"},"budget":{"setup_seconds":3,"workspace_bytes":0,"grader_bytes":0},"data":{"generator":"generate.py","rows":1500}}$mf7a385943$::jsonb, 'lab-bundles/4f094cb9059a81762404d2dc8182d97b29eb43038da352318d7a21b22084a41a.tar.gz', '4f094cb9059a81762404d2dc8182d97b29eb43038da352318d7a21b22084a41a', NULL)
