-- seed.fa-small@1.0.0
INSERT INTO public.lab_blocks (id, org_id, block_key, kind, stack)
VALUES ('4f880863-e754-5c19-af9a-a6f7ac0e18ee', NULL, 'seed.fa-small', 'data', 'fastapi')
